(window.BANKS = window.BANKS || []).push({"kode": "KUI001", "matkul": "Bahasa Indonesia", "singkat": "BI", "warna": "#c2410c", "semester": 1, "uts": "P07", "genInfo": "ejaan dan kalimat: kata baku, huruf kapital, di- vs di, partikel pun, penulisan angka, singkatan dan gelar, tanda baca, kalimat tidak efektif (pleonasme), konjungsi, dan jenis paragraf", "catatan": "Soal disusun dari Materi 1–3, BAB 5–9, dan Metode Penulisan Referensi Ilmiah mata kuliah Bahasa Indonesia SiberMu. Soal bertanda \"Pola UTS\" ditulis ulang mengikuti pola kuis/UTS Bahasa Indonesia SiberMu.", "topics": [{"id": "P01", "judul": "Sejarah, Kedudukan, Fungsi, dan Ragam Bahasa Indonesia", "sumber": ["MATERI 1"], "ringkasan": ["Bahasa Indonesia berakar dari bahasa Melayu; dikukuhkan dalam Sumpah Pemuda 28 Oktober 1928 ('menjunjung bahasa persatuan, bahasa Indonesia').", "Tonggak ejaan: Van Ophuijsen (1901), Ejaan Republik/Soewandi (1947), EYD (diresmikan 16 Agustus 1972), EBI (2015), EYD Edisi V (16 Agustus 2022).", "Kongres Bahasa Indonesia I: Solo, 25–28 Juni 1938; Kongres II: Medan 1954.", "Kedudukan sebagai bahasa nasional (Sumpah Pemuda): lambang kebanggaan nasional, lambang identitas nasional, alat pemersatu, alat perhubungan antardaerah dan antarbudaya.", "Kedudukan sebagai bahasa negara (UUD 1945 Pasal 36): bahasa resmi kenegaraan, pengantar pendidikan, perhubungan tingkat nasional, pengembangan kebudayaan dan iptek.", "Ragam bahasa: lisan dan tulis; resmi (baku) dan tidak resmi."], "tags": {"sejarah": "Sejarah & ejaan", "kedudukan": "Kedudukan & fungsi", "ragam": "Ragam bahasa"}, "media": []}, {"id": "P02", "judul": "Penerapan Ejaan Bahasa Indonesia (EYD V)", "sumber": ["MATERI 2"], "ringkasan": ["Huruf kapital dipakai pada awal kalimat, nama orang, nama agama/kitab suci/Tuhan, gelar yang diikuti nama, nama geografi, nama lembaga, judul (kecuali kata tugas), hari/bulan/hari raya.", "Nama arah (barat, selatan) tidak dikapitalkan bila tidak menjadi nama geografi.", "Awalan di- ditulis serangkai (ditulis), kata depan di ditulis terpisah (di rumah); partikel pun dipisah kecuali pada kata yang sudah padu (walaupun, meskipun, adapun).", "Angka di awal kalimat ditulis dengan huruf; bilangan yang dapat ditulis dengan satu atau dua kata ditulis dengan huruf.", "Gelar akademik ditulis setelah nama dengan koma: Rina Kartika, S.Kom.; singkatan umum tiga huruf diikuti titik (dll., dsb., yth.).", "Tanda koma dipakai sebelum kata penghubung tetapi, melainkan, sedangkan; di antara unsur rincian; dan setelah anak kalimat yang mendahului induk kalimat."], "tags": {"kapital": "Huruf kapital", "kata": "Penulisan kata (di-, pun, gabungan)", "angka": "Angka, singkatan, gelar", "tandabaca": "Tanda baca", "huruf": "Huruf miring & tebal"}, "media": []}, {"id": "P04", "judul": "Pembentukan Kata, Kata Baku, dan Diksi", "sumber": ["MATERI 3"], "ringkasan": ["Pembentukan kata melibatkan kata dasar, kata serapan, dan imbuhan.", "Unsur serapan: belum terserap penuh (reshuffle, shuttle cock) dan yang disesuaikan kaidah; cara: adopsi, adaptasi, penerjemahan.", "Afiksasi: prefiks (awalan ber-, me-, di-, ter-, ke-, se-, pe-), infiks (sisipan -el-, -em-, -er-: telunjuk), sufiks (akhiran -an, -i, -kan, -nya), konfiks (ke-an, pe-an, per-an, ber-an).", "Imbuhan asing (multi-, anti-, semi-, non-, pra-) dan daerah/Sanskerta (tuna-, nara-, pasca-, swa-, maha-, antar-) ditulis serangkai.", "Peluluhan: k, p, t, s di awal kata dasar luluh bila diberi me-/pe- (memukul, menulis, menyapu), kecuali gugus konsonan (memproduksi, memprotes).", "Diksi = pemilihan kata yang tepat, benar, dan lazim; perhatikan sinonim, makna denotasi (sebenarnya) dan konotasi (nilai rasa)."], "tags": {"imbuhan": "Imbuhan & peluluhan", "serapan": "Kata serapan & kata baku", "diksi": "Diksi & makna kata"}, "media": []}, {"id": "P05", "judul": "Penulisan Kalimat Efektif", "sumber": ["BAB 5", "Materi 6"], "ringkasan": ["Kalimat = satuan bahasa terkecil yang mengungkapkan pikiran utuh; minimal terdiri atas subjek dan predikat.", "Kalimat efektif = kalimat yang benar secara tata bahasa dan makna sehingga gagasan penulis diterima pembaca dengan tepat.", "Ciri kalimat efektif: kesepadanan, kecermatan pilihan kata, kehematan, kelogisan, kepaduan, keparalelan, ketegasan.", "Kehematan: hindari pleonasme (adalah merupakan, naik ke atas, para mahasiswa-mahasiswa, agar supaya, sangat … sekali).", "Kesepadanan: subjek tidak didahului kata depan (Di daerah Banyumas mempromosikan… → Daerah Banyumas mempromosikan…).", "Keparalelan: bentuk kata dalam rincian harus sejajar (pengetikan, pemeriksaan, penjilidan)."], "tags": {"definisi": "Kalimat & kalimat efektif", "ciri": "Ciri kalimat efektif", "hemat": "Kehematan & kesepadanan"}, "media": []}, {"id": "P06", "judul": "Analisis Struktur dan Jenis Kalimat", "sumber": ["BAB 5"], "ringkasan": ["Fungsi sintaksis: subjek (S), predikat (P), objek (O), pelengkap (Pel), keterangan (K).", "Objek dapat menjadi subjek dalam kalimat pasif; pelengkap tidak dapat.", "Keterangan paling mudah berpindah letak.", "Berdasarkan bentuk sintaksis: deklaratif (berita), imperatif (perintah), interogatif (tanya), eksklamatif (seru).", "Kalimat tunggal = satu klausa; kalimat majemuk = dua klausa atau lebih: setara (dan, atau, tetapi), bertingkat (karena, ketika, jika), campuran."], "tags": {"fungsi": "Fungsi S-P-O-Pel-K", "jenis": "Jenis kalimat", "majemuk": "Kalimat majemuk & konjungsi"}, "media": []}, {"id": "P07", "judul": "Penyusunan dan Pengembangan Paragraf", "sumber": ["BAB 9"], "ringkasan": ["Paragraf = bagian karangan berisi beberapa kalimat yang berkaitan dan membicarakan satu gagasan.", "Syarat paragraf: kepaduan (koherensi), kesatuan (satu gagasan pokok), kelengkapan (gagasan tuntas).", "Alat kepaduan: repetisi kata kunci, kata ganti, kata transisi, urutan isi.", "Berdasarkan letak kalimat utama: deduktif (awal), induktif (akhir), campuran/ineratif (awal dan akhir).", "Berdasarkan isi: argumentasi, eksposisi, deskripsi, persuasi, narasi."], "tags": {"syarat": "Syarat paragraf", "letak": "Jenis berdasarkan letak kalimat utama", "isi": "Jenis berdasarkan isi", "kembang": "Teknik pengembangan paragraf"}, "media": []}, {"id": "P09", "judul": "Penulisan Paragraf Argumentasi", "sumber": ["BAB 9 (argumentasi)"], "ringkasan": ["Paragraf argumentasi berisi pendapat yang didukung alasan, data, atau fakta untuk meyakinkan pembaca.", "Bedanya dengan persuasi: argumentasi meyakinkan dengan bukti, persuasi mengajak pembaca melakukan sesuatu.", "Pola penalaran: deduktif (umum → khusus), induktif (khusus → umum: generalisasi, analogi, sebab-akibat).", "Bukti dapat berupa data statistik, hasil penelitian, kutipan ahli, dan contoh nyata."], "tags": {"argumen": "Ciri argumentasi", "penalaran": "Pola penalaran"}, "media": []}, {"id": "P10", "judul": "Pengantar Penulisan Ilmiah", "sumber": ["BAB 7", "BAB 8"], "ringkasan": ["Karya tulis ilmiah disusun dengan metode ilmiah, bahasa baku, objektif, sistematis, dan didukung data/referensi.", "Langkah: menentukan topik → merumuskan masalah, tujuan, ruang lingkup → mengumpulkan bahan → menyusun kerangka → menulis.", "Topik = pokok pembicaraan; tema = amanat utama karangan (Keraf).", "Penelitian kualitatif menghasilkan temuan deskriptif yang tidak diperoleh dengan prosedur statistik; kuantitatif memakai angka/statistik (positivisme).", "Simpulan adalah jawaban atas rumusan masalah."], "tags": {"ciri": "Ciri & langkah karya ilmiah", "penelitian": "Kualitatif vs kuantitatif", "sistematika": "Sistematika makalah & skripsi"}, "media": []}, {"id": "P11", "judul": "Pengembangan Paragraf Ilmiah dan Referensi", "sumber": ["Metode Penulisan Referensi Ilmiah", "Contoh Tugas 2"], "ringkasan": ["Referensi ditulis dalam bentuk kutipan dan daftar pustaka.", "Kutipan: bodynote/catatan perut di dalam teks (Ahmad, 2015) dan footnote/catatan kaki di bawah halaman.", "Bentuk bodynote: Menurut Ahmad (2015), …; Ahmad (2015) menjelaskan …; … (Ahmad, 2015).", "Kutipan bisa ditulis manual, dengan fitur referensi MS Word, atau aplikasi pengelola referensi (Mendeley, Zotero, EndNote).", "Daftar pustaka disusun alfabetis berdasarkan nama belakang penulis; format APA: Nama, Inisial. (Tahun). Judul. Penerbit/Jurnal, Vol(No), halaman."], "tags": {"kutipan": "Kutipan (bodynote & footnote)", "pustaka": "Daftar pustaka & aplikasi referensi"}, "media": []}], "questions": [{"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Ejaan resmi pertama bahasa Melayu tahun 1901 disusun oleh…", "opts": ["Ch. A. van Ophuijsen", "Soewandi", "Sutan Takdir Alisjahbana", "Ki Hajar Dewantara", "Mohammad Yamin"], "ans": 0, "why": "Ejaan Van Ophuijsen (1901).", "lvl": 1, "code": null, "src": "modul", "id": "P01-001"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Ejaan yang berlaku saat ini, ditetapkan 16 Agustus 2022, bernama…", "opts": ["EYD Edisi V", "EBI", "Ejaan Soewandi", "Ejaan Van Ophuijsen", "EYD 1972"], "ans": 0, "why": "EYD Edisi V ditetapkan 16 Agustus 2022.", "lvl": 1, "code": null, "src": "modul", "id": "P01-002"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Kongres Bahasa Indonesia I diselenggarakan pada 1938 di…", "opts": ["Solo", "Medan", "Jakarta", "Yogyakarta", "Bandung"], "ans": 0, "why": "Kongres I: Solo, 25–28 Juni 1938.", "lvl": 1, "code": null, "src": "modul", "id": "P01-003"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Kedudukan bahasa Indonesia sebagai bahasa negara tercantum dalam…", "opts": ["UUD 1945 Pasal 36", "Sumpah Pemuda", "Proklamasi", "Pancasila sila ketiga", "Kongres Bahasa I"], "ans": 0, "why": "Bahasa nasional berdasar Sumpah Pemuda; bahasa negara berdasar UUD 1945 Pasal 36.", "lvl": 1, "code": null, "src": "modul", "id": "P01-004"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Fungsi bahasa Indonesia sebagai lambang identitas nasional termasuk kedudukannya sebagai…", "opts": ["Bahasa nasional", "Bahasa negara", "Bahasa daerah", "Bahasa asing", "Bahasa ilmiah"], "ans": 0, "why": "Sebagai bahasa nasional: lambang kebanggaan, identitas, pemersatu, perhubungan antardaerah.", "lvl": 1, "code": null, "src": "modul", "id": "P01-005"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Bahasa Indonesia sebagai bahasa pengantar di perguruan tinggi menjalankan fungsinya sebagai…", "opts": ["Bahasa negara", "Bahasa nasional", "Bahasa daerah", "Bahasa pergaulan", "Bahasa sastra"], "ans": 0, "why": "Pengantar pendidikan adalah fungsi bahasa negara.", "lvl": 1, "code": null, "src": "modul", "id": "P01-006"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam bahasa yang digunakan dalam karya ilmiah dan surat dinas adalah…", "opts": ["Ragam resmi (baku)", "Ragam santai", "Ragam akrab", "Ragam lisan pasar", "Bahasa gaul"], "ans": 0, "why": "Situasi resmi menuntut ragam baku.", "lvl": 1, "code": null, "src": "modul", "id": "P01-007"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Alasan utama bahasa Melayu dipilih sebagai cikal bakal bahasa Indonesia adalah…", "opts": ["Sudah menjadi lingua franca di Nusantara dan tidak memiliki tingkatan tutur", "Penuturnya paling banyak di Indonesia", "Dipakai oleh pemerintah kolonial Belanda", "Memiliki aksara sendiri yang paling tua"], "ans": 0, "why": "Melayu sudah jadi bahasa pengantar antarsuku sejak masa kerajaan dan tidak punya tingkatan bahasa seperti bahasa Jawa, sehingga mudah diterima semua suku.", "lvl": 1, "code": null, "src": "modul", "id": "P01-008"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Prasasti Kota Kapur yang berbahasa Melayu Kuno ditemukan di…", "opts": ["Bangka", "Palembang", "Jambi", "Maluku"], "ans": 0, "why": "Kota Kapur (686 M) ditemukan di Bangka; Talang Tuo di Palembang; Karang Berahi di Jambi.", "lvl": 2, "code": null, "src": "modul", "id": "P01-009"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Badan penerbit yang didirikan pada 1908 dan kelak bernama Balai Pustaka adalah…", "opts": ["Commissie voor de Volkslectuur", "Pujangga Baru", "Kitab Logat Melayu", "Pusat Bahasa"], "ans": 0, "why": "Commissie voor de Volkslectuur (1908) kemudian menjadi Balai Pustaka.", "lvl": 2, "code": null, "src": "modul", "id": "P01-010"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Peristiwa yang menetapkan bahasa Indonesia sebagai bahasa persatuan adalah…", "opts": ["Sumpah Pemuda, 28 Oktober 1928", "Proklamasi, 17 Agustus 1945", "Pengesahan UUD 1945, 18 Agustus 1945", "Kongres Bahasa Indonesia I, 1938"], "ans": 0, "why": "Ikrar ketiga Sumpah Pemuda: 'menjunjung bahasa persatuan, bahasa Indonesia'.", "lvl": 1, "code": null, "src": "modul", "id": "P01-011"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Selain bahasa Melayu, bahasa Indonesia juga menyerap unsur dari bahasa berikut, KECUALI…", "opts": ["Bahasa Latin kuno sebagai sumber utama", "Bahasa Arab", "Bahasa Belanda", "Bahasa Sanskerta"], "ans": 0, "why": "Modul menyebut Arab, Portugis, Belanda, Inggris, Sanskerta, dan bahasa daerah. Latin tidak disebut sebagai sumber utama.", "lvl": 2, "code": null, "src": "modul", "id": "P01-012"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Kedudukan bahasa Indonesia sebagai bahasa negara tercantum dalam…", "opts": ["UUD 1945 Bab XV Pasal 36", "Ikrar Sumpah Pemuda", "Keputusan Presiden No. 57 Tahun 1972", "Permendikbud No. 50 Tahun 2015"], "ans": 0, "why": "Pasal 36 UUD 1945: 'Bahasa negara ialah bahasa Indonesia'. Sumpah Pemuda adalah dasar kedudukan sebagai bahasa nasional.", "lvl": 1, "code": null, "src": "modul", "id": "P01-013"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Fungsi bahasa Indonesia sebagai bahasa NASIONAL adalah…", "opts": ["Lambang identitas nasional", "Bahasa pengantar di dunia pendidikan", "Bahasa resmi kenegaraan", "Alat pengembangan iptek"], "ans": 0, "why": "Fungsi bahasa nasional: lambang kebanggaan, lambang identitas, pemersatu, penghubung antardaerah. Tiga opsi lain adalah fungsi bahasa negara.", "lvl": 1, "code": null, "src": "modul", "id": "P01-014"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Fungsi bahasa Indonesia sebagai bahasa NEGARA adalah…", "opts": ["Bahasa pengantar dalam pendidikan", "Lambang kebanggaan nasional", "Alat pemersatu suku bangsa", "Penghubung antarbudaya dan antardaerah"], "ans": 0, "why": "Fungsi bahasa negara: resmi kenegaraan, pengantar pendidikan, perhubungan tingkat nasional, pengembangan kebudayaan & iptek.", "lvl": 1, "code": null, "src": "modul", "id": "P01-015"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Fungsi dan kedudukan bahasa Indonesia dirumuskan secara resmi dalam…", "opts": ["Seminar Politik Bahasa Nasional 1975", "Kongres Bahasa Indonesia I 1938", "Sumpah Pemuda 1928", "Kongres Bahasa Indonesia X 2013"], "ans": 0, "why": "Seminar Politik Bahasa Nasional di Jakarta, 25—28 Februari 1975.", "lvl": 2, "code": null, "src": "modul", "id": "P01-016"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Seorang dosen menyampaikan kuliah dalam bahasa Indonesia. Fungsi bahasa Indonesia yang tampak adalah…", "opts": ["Bahasa pengantar pendidikan (bahasa negara)", "Lambang kebanggaan nasional", "Lambang identitas nasional", "Pemberi kekhasan"], "ans": 0, "why": "Bahasa pengantar di dunia pendidikan adalah fungsi bahasa Indonesia sebagai bahasa negara.", "lvl": 2, "code": null, "src": "modul", "id": "P01-017"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Menurut data Badan Bahasa hingga Juni 2025, lembaga BIPA tersebar di… negara.", "opts": ["57", "111", "54", "300"], "ans": 0, "why": "772 lembaga BIPA di 57 negara. (111 = jumlah asal negara pemelajar BIPA 2019; 54 = jumlah universitas.)", "lvl": 3, "code": null, "src": "modul", "id": "P01-018"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Potensi bahasa Indonesia menjadi bahasa internasional didukung oleh sifatnya, KECUALI…", "opts": ["Memiliki tingkatan tutur yang ketat", "Demokratis", "Terbuka terhadap unsur asing", "Mulai mengglobal"], "ans": 0, "why": "Bahasa Indonesia justru TIDAK mengenal tingkatan tutur, itulah yang membuatnya demokratis.", "lvl": 1, "code": null, "src": "modul", "id": "P01-019"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Bahasa yang dipakai untuk menjelaskan ilmu bahasa itu sendiri disebut fungsi…", "opts": ["metalingual", "pemersatu", "kerangka acuan", "pembawa kewibawaan"], "ans": 0, "why": "Dalam fungsi pendidikan, bahasa yang menjelaskan ilmu bahasa disebut metalingual.", "lvl": 2, "code": null, "src": "modul", "id": "P01-020"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Empat fungsi bahasa menurut Alwi dkk. adalah pemersatu, pemberi kekhasan, pembawa kewibawaan, dan…", "opts": ["kerangka acuan", "alat ekspresi diri", "alat kontrol sosial", "bahasa resmi"], "ans": 0, "why": "Fungsi umum menurut Alwi dkk. (2003): pemersatu, pemberi kekhasan, pembawa kewibawaan, kerangka acuan.", "lvl": 1, "code": null, "src": "modul", "id": "P01-021"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Ragam bahasa yang ringkas, tegas, dan penuh singkatan serta akronim merupakan ciri bahasa pada bidang…", "opts": ["militer", "hukum", "agama", "sastra"], "ans": 0, "why": "Bahasa militer dikenal ringkas, tegas, dan penuh singkatan sesuai kehidupan yang disiplin.", "lvl": 1, "code": null, "src": "modul", "id": "P01-022"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Pada bidang hukum, penggunaan bahasa harus sangat cermat terutama pada…", "opts": ["tanda baca, konjungsi, dan diksi denotatif", "gaya bahasa kiasan", "kata-kata konotatif", "bahasa daerah"], "ans": 0, "why": "Bahasa hukum memakai tanda baca, kata hubung, dan diksi bermakna denotatif agar tidak menimbulkan tafsir ganda.", "lvl": 2, "code": null, "src": "modul", "id": "P01-023"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Komunikasi yang memakai bunyi peluit, cahaya, atau suara alat disebut komunikasi…", "opts": ["nonverbal", "verbal", "dua arah", "linguistik"], "ans": 0, "why": "Komunikasi nonverbal memakai alat bukan bahasa, asalkan kodenya dipahami bersama.", "lvl": 1, "code": null, "src": "modul", "id": "P01-024"}, {"p": "P01", "tag": "kedudukan", "type": "mcq", "q": "Khotbah atau ceramah yang tidak diikuti tanya jawab adalah contoh komunikasi…", "opts": ["searah", "dua arah", "nonverbal", "paralinguistik"], "ans": 0, "why": "Pada komunikasi searah, pengirim tetap pengirim dan penerima tetap penerima.", "lvl": 1, "code": null, "src": "modul", "id": "P01-025"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam bahasa yang bersifat perorangan (warna suara, pilihan kata, gaya) disebut…", "opts": ["idiolek", "dialek", "kronolek", "sosiolek"], "ans": 0, "why": "Idiolek = variasi bahasa milik tiap individu.", "lvl": 1, "code": null, "src": "modul", "id": "P01-026"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam bahasa Indonesia tahun 1930-an berbeda dengan masa kini. Ragam berdasarkan masa ini disebut…", "opts": ["kronolek", "dialek", "sosiolek", "fungsiolek"], "ans": 0, "why": "Kronolek atau dialek temporal adalah ragam bahasa kelompok sosial pada masa tertentu.", "lvl": 1, "code": null, "src": "modul", "id": "P01-027"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam bahasa yang berkaitan dengan status, golongan, dan kelas sosial penutur disebut…", "opts": ["sosiolek", "idiolek", "kronolek", "dialek"], "ans": 0, "why": "Sosiolek berhubungan dengan usia, pendidikan, pekerjaan, keadaan sosial ekonomi, dll.", "lvl": 1, "code": null, "src": "modul", "id": "P01-028"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Bahasa Jawa dialek Banyumas dan Surabaya adalah contoh ragam berdasarkan…", "opts": ["wilayah (dialek regional)", "masa (kronolek)", "status sosial (sosiolek)", "bidang pemakaian (fungsiolek)"], "ans": 0, "why": "Dialek didasarkan pada wilayah tempat tinggal penutur, disebut juga dialek areal/regional.", "lvl": 1, "code": null, "src": "modul", "id": "P01-029"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam bahasa yang dipakai pada khotbah dan upacara kenegaraan, dengan pola yang tidak boleh diubah, disebut ragam…", "opts": ["beku (frozen)", "baku (formal)", "usaha (konsultatif)", "akrab (intim)"], "ans": 0, "why": "Ragam beku dipakai pada situasi sangat khidmat; kaidahnya sudah mantap dan tidak boleh diubah.", "lvl": 2, "code": null, "src": "modul", "id": "P01-030"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam yang berada di antara formal dan santai, lazim dipakai dalam rapat atau negosiasi bisnis, disebut ragam…", "opts": ["usaha (konsultatif)", "beku", "baku", "kasual"], "ans": 0, "why": "Ragam usaha adalah ragam paling operasional, berorientasi pada hasil.", "lvl": 2, "code": null, "src": "modul", "id": "P01-031"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam bahasa yang ditandai bentuk alegro (kata dipendekkan) dan unsur bahasa daerah adalah ragam…", "opts": ["santai (kasual)", "beku", "baku", "usaha"], "ans": 0, "why": "Ragam kasual banyak memakai bentuk alegro dan unsur leksikal dialek/daerah.", "lvl": 2, "code": null, "src": "modul", "id": "P01-032"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ragam bahasa berdasarkan bidang pemakaiannya (ilmiah, jurnalistik, sastra) disebut…", "opts": ["fungsiolek", "sosiolek", "idiolek", "kronolek"], "ans": 0, "why": "Fungsiolek paling tampak cirinya pada kosakata khusus setiap bidang.", "lvl": 1, "code": null, "src": "modul", "id": "P01-033"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Ciri ragam bahasa jurnalistik adalah…", "opts": ["sederhana, komunikatif, dan ringkas", "estetis dan penuh kiasan", "beku dan tidak boleh diubah", "intim dan tidak lengkap"], "ans": 0, "why": "Jurnalistik: sederhana (mudah dipahami), komunikatif, ringkas (keterbatasan ruang dan waktu).", "lvl": 1, "code": null, "src": "modul", "id": "P01-034"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Bagi kebanyakan anak Indonesia, bahasa Indonesia berkedudukan sebagai…", "opts": ["bahasa kedua (B2)", "bahasa ibu (B1)", "bahasa asing", "bahasa ketiga"], "ans": 0, "why": "Umumnya B1 adalah bahasa daerah; bahasa Indonesia dipelajari saat masuk sekolah sehingga menjadi B2.", "lvl": 2, "code": null, "src": "modul", "id": "P01-035"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Faktor penyebab ragam bahasa menurut modul, KECUALI…", "opts": ["Jenis kelamin hewan peliharaan", "Letak geografis", "Situasi/kondisi", "Jenis pekerjaan"], "ans": 0, "why": "Faktor: letak geografis, media/sarana, situasi, tingkat pendidikan, jenis pekerjaan.", "lvl": 1, "code": null, "src": "modul", "id": "P01-036"}, {"p": "P01", "tag": "ragam", "type": "mcq", "q": "Gaya bahasa yang dipakai dalam amanat kepresidenan, berita negara, dan pidato resmi adalah gaya bahasa…", "opts": ["resmi", "tak resmi", "percakapan", "akrab"], "ans": 0, "why": "Gaya bahasa resmi = bentuk lengkap untuk kesempatan resmi dan esai yang serius.", "lvl": 2, "code": null, "src": "modul", "id": "P01-037"}, {"p": "P01", "tag": "sejarah", "type": "tf", "q": "Bahasa Indonesia lebih tua daripada usia kemerdekaan Indonesia.", "opts": null, "ans": 1, "why": "Bahasa Indonesia ditetapkan sebagai bahasa persatuan 1928, sebelum merdeka 1945.", "lvl": 1, "code": null, "src": "modul", "id": "P01-038"}, {"p": "P01", "tag": "kedudukan", "type": "tf", "q": "Dasar kedudukan bahasa Indonesia sebagai bahasa nasional adalah UUD 1945 Pasal 36.", "opts": null, "ans": 0, "why": "Bahasa NASIONAL berdasar Sumpah Pemuda 1928. UUD 1945 Pasal 36 adalah dasar bahasa NEGARA.", "lvl": 1, "code": null, "src": "modul", "id": "P01-039"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Ejaan yang mengganti 'oe' menjadi 'u' dan membolehkan kata ulang ditulis dengan angka 2 adalah…", "opts": ["Ejaan Republik (Soewandi)", "Ejaan van Ophuijsen", "EYD 1972", "PUEBI"], "ans": 0, "why": "Ejaan Soewandi (19 Maret 1947): oe→u, hamzah→k, kata ulang boleh angka 2, di- selalu serangkai.", "lvl": 1, "code": null, "src": "modul", "id": "P01-040"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Penulisan 'jang' dan 'itoe' merupakan ciri ejaan…", "opts": ["van Ophuijsen", "Soewandi", "Melindo", "EYD"], "ans": 0, "why": "Van Ophuijsen memakai j untuk bunyi y dan oe untuk bunyi u.", "lvl": 1, "code": null, "src": "modul", "id": "P01-041"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Ejaan hasil kerja sama Indonesia-Melayu (1959) yang batal diberlakukan adalah…", "opts": ["Ejaan Melindo", "Ejaan Soewandi", "PUEBI", "EYD"], "ans": 0, "why": "Ejaan Melindo batal karena perkembangan politik.", "lvl": 2, "code": null, "src": "modul", "id": "P01-042"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Urutan ejaan bahasa Indonesia dari yang paling lama adalah…", "opts": ["van Ophuijsen – Soewandi – EYD – PUEBI – EYD V", "Soewandi – van Ophuijsen – EYD – PUEBI – EYD V", "van Ophuijsen – EYD – Soewandi – PUEBI – EYD V", "van Ophuijsen – Soewandi – PUEBI – EYD – EYD V"], "ans": 0, "why": "1901 van Ophuijsen → 1947 Soewandi → 1972 EYD → 2015 PUEBI → 2022 EYD Edisi V.", "lvl": 1, "code": null, "src": "modul", "id": "P01-043"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "PUEBI ditetapkan melalui…", "opts": ["Permendikbud Nomor 50 Tahun 2015", "Keppres Nomor 57 Tahun 1972", "Permendiknas Nomor 46 Tahun 2009", "UUD 1945 Pasal 36"], "ans": 0, "why": "PUEBI: Permendikbud No. 50/2015 (30 November 2015). EYD 1972: Keppres No. 57/1972.", "lvl": 3, "code": null, "src": "modul", "id": "P01-044"}, {"p": "P01", "tag": "sejarah", "type": "mcq", "q": "Ejaan bahasa Indonesia yang berlaku sejak 2022 adalah…", "opts": ["Ejaan Bahasa Indonesia yang Disempurnakan Edisi V", "Pedoman Umum Ejaan Bahasa Indonesia", "Ejaan Soewandi", "Ejaan van Ophuijsen"], "ans": 0, "why": "Keputusan Kepala Badan Bahasa No. 0424/I/BS.00.01/2022 menetapkan EYD Edisi V.", "lvl": 1, "code": null, "src": "uts", "id": "P01-045"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan huruf kapital yang benar adalah…", "opts": ["Kami berlibur ke Jawa Barat bulan Desember.", "Kami berlibur ke jawa barat bulan desember.", "Kami berlibur ke Jawa barat bulan Desember.", "kami berlibur ke Jawa Barat Bulan Desember.", "Kami Berlibur ke Jawa Barat bulan desember."], "ans": 0, "why": "Nama geografi dan nama bulan ditulis kapital.", "lvl": 1, "code": null, "src": "modul", "id": "P02-001"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Kata arah tidak dikapitalkan bila tidak menjadi nama geografi. Kalimat yang benar adalah…", "opts": ["Candi itu berdiri di lereng barat Gunung Lawu.", "Candi itu berdiri di Lereng Barat gunung Lawu.", "Candi itu berdiri di lereng Barat gunung lawu.", "Candi itu berdiri di Lereng barat gunung Lawu.", "candi itu berdiri di lereng barat Gunung Lawu."], "ans": 0, "why": "'lereng barat' bukan nama diri; 'Gunung Lawu' nama geografi.", "lvl": 2, "code": null, "src": "modul", "id": "P02-002"}, {"p": "P02", "tag": "kata", "type": "mcq", "q": "Penulisan kata depan dan awalan yang benar adalah…", "opts": ["Buku itu ditaruh di atas meja.", "Buku itu di taruh diatas meja.", "Buku itu ditaruh diatas meja.", "Buku itu di taruh di atas meja.", "Buku itu ditaruh di-atas meja."], "ans": 0, "why": "Awalan di- serangkai (ditaruh); kata depan di terpisah (di atas).", "lvl": 1, "code": null, "src": "modul", "id": "P02-003"}, {"p": "P02", "tag": "kata", "type": "mcq", "q": "Penulisan partikel pun yang benar adalah…", "opts": ["Apa pun yang terjadi, ia tetap datang walaupun hujan.", "Apapun yang terjadi, ia tetap datang walau pun hujan.", "Apa pun yang terjadi, ia tetap datang walau pun hujan.", "Apapun yang terjadi, ia tetap datang walaupun hujan.", "Apa-pun yang terjadi, ia tetap datang walaupun hujan."], "ans": 0, "why": "pun dipisah (apa pun), kecuali kata padu (walaupun).", "lvl": 1, "code": null, "src": "modul", "id": "P02-004"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Kalimat 'Harga buku itu seratus ribu rupiah' bila ditulis dengan angka yang benar adalah…", "opts": ["Rp100.000,00", "Rp. 100.000,-", "Rp 100,000.00", "100.000 Rp", "Rp.100.000"], "ans": 0, "why": "Lambang mata uang Rp tanpa titik, angka memakai titik ribuan dan koma desimal.", "lvl": 2, "code": null, "src": "modul", "id": "P02-005"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Perbaikan kalimat 'Pada tahun 90an diadakan pertemuan se Indonesia' yang benar adalah…", "opts": ["Pada tahun 90-an diadakan pertemuan se-Indonesia.", "Pada tahun 90 an diadakan pertemuan se-indonesia.", "Pada tahun 90an diadakan pertemuan seIndonesia.", "Pada tahun sembilan puluhan diadakan pertemuan se Indonesia.", "Pada tahun 90-an diadakan pertemuan se Indonesia."], "ans": 0, "why": "Tanda hubung pada 90-an dan se- di depan kata berhuruf kapital.", "lvl": 2, "code": null, "src": "modul", "id": "P02-006"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan nama dan gelar akademik yang benar adalah…", "opts": ["Rina Kartika, S.Kom., M.T.", "Rina Kartika S.Kom, M.T", "Rina Kartika, S.Kom, MT.", "Rina Kartika. S.Kom. M.T.", "Rina Kartika,S.Kom.,M.T."], "ans": 0, "why": "Gelar diletakkan setelah koma dan setiap singkatan gelar diakhiri titik.", "lvl": 1, "code": null, "src": "modul", "id": "P02-007"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Pemakaian tanda koma yang benar adalah…", "opts": ["Saya ingin ikut, tetapi hari ini ada ujian.", "Saya ingin ikut tetapi, hari ini ada ujian.", "Saya, ingin ikut tetapi hari ini ada ujian.", "Saya ingin ikut tetapi hari ini, ada ujian.", "Saya ingin, ikut tetapi hari ini ada ujian."], "ans": 0, "why": "Koma dipakai sebelum kata penghubung tetapi.", "lvl": 1, "code": null, "src": "modul", "id": "P02-008"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Pemakaian koma yang benar karena anak kalimat mendahului induk kalimat adalah…", "opts": ["Karena hujan deras, acara ditunda.", "Acara ditunda, karena hujan deras.", "Karena hujan, deras acara ditunda.", "Karena, hujan deras acara ditunda.", "Acara, ditunda karena hujan deras."], "ans": 0, "why": "Koma setelah anak kalimat yang mendahului induk; tidak dipakai bila anak kalimat di belakang.", "lvl": 2, "code": null, "src": "modul", "id": "P02-009"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan yang benar adalah…", "opts": ["Pamannya baru saja dilantik menjadi bupati.", "Pamannya baru saja dilantik menjadi Bupati.", "Pamannya baru saja dilantik menjadi Bupati Daerah.", "pamannya baru saja dilantik menjadi bupati."], "ans": 0, "why": "Nama jabatan yang TIDAK diikuti nama orang/instansi/tempat tidak ditulis kapital.", "lvl": 1, "code": null, "src": "modul", "id": "P02-010"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan nama geografi yang benar adalah…", "opts": ["Kami mendaki Gunung Merapi lalu menuruni lembah.", "Kami mendaki gunung Merapi lalu menuruni lembah.", "Kami mendaki Gunung Merapi lalu menuruni Lembah.", "Kami mendaki gunung merapi lalu menuruni lembah."], "ans": 0, "why": "Unsur geografi yang diikuti nama diri ditulis kapital (Gunung Merapi); yang tidak diikuti nama diri tidak (lembah).", "lvl": 1, "code": null, "src": "modul", "id": "P02-011"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan yang benar menurut EYD adalah…", "opts": ["Ia membeli pisang ambon dan batik Pekalongan.", "Ia membeli pisang Ambon dan batik Pekalongan.", "Ia membeli Pisang Ambon dan Batik Pekalongan.", "Ia membeli pisang ambon dan batik pekalongan."], "ans": 0, "why": "Nama geografi sebagai penjelas nama jenis tidak kapital (pisang ambon); nama tempat setelah unsur khas budaya tetap kapital (batik Pekalongan).", "lvl": 2, "code": null, "src": "modul", "id": "P02-012"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan nama orang yang benar adalah…", "opts": ["Abdullah bin Rahmad", "Abdullah Bin Rahmad", "abdullah bin Rahmad", "Abdullah bin rahmad"], "ans": 0, "why": "Kata bin/binti dalam nama orang tidak ditulis kapital.", "lvl": 1, "code": null, "src": "modul", "id": "P02-013"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan yang benar adalah…", "opts": ["Mereka sangat menyukai kejawa-jawaan.", "Mereka sangat menyukai keJawa-Jawaan.", "Mereka sangat menyukai keJawa-jawaan.", "Mereka sangat menyukai Kejawa-jawaan."], "ans": 0, "why": "Nama suku/bangsa yang menjadi dasar kata turunan tidak ditulis kapital.", "lvl": 2, "code": null, "src": "modul", "id": "P02-014"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan kata sapaan yang benar adalah…", "opts": ["Kapan Bapak berangkat ke Bandung?", "Kapan bapak berangkat ke Bandung?", "Dia tidak mempunyai Saudara di Semarang.", "Surat anda sudah saya terima."], "ans": 0, "why": "Kata kekerabatan kapital jika dipakai menyapa; tidak kapital jika tidak menyapa/mengacu. 'Anda' selalu kapital.", "lvl": 1, "code": null, "src": "modul", "id": "P02-015"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan judul buku dalam kalimat yang benar adalah…", "opts": ["Saya membaca buku Uji Kemahiran Bahasa Indonesia.", "Saya membaca buku uji kemahiran bahasa Indonesia.", "Saya membaca Buku Uji Kemahiran Bahasa Indonesia.", "Saya membaca buku Uji Kemahiran bahasa Indonesia."], "ans": 0, "why": "Semua kata dalam judul buku diawali kapital, kecuali kata tugas yang tidak di awal.", "lvl": 1, "code": null, "src": "modul", "id": "P02-016"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan nama hari dan peristiwa yang benar adalah…", "opts": ["Soekarno-Hatta memproklamasikan kemerdekaan pada hari Jumat.", "Soekarno-Hatta memproklamasikan Kemerdekaan pada Hari Jumat.", "Soekarno-Hatta memproklamasikan kemerdekaan pada hari jumat.", "Soekarno-Hatta memproklamasikan Kemerdekaan pada hari Jumat."], "ans": 0, "why": "Nama hari kapital (Jumat), 'hari' tidak. Peristiwa sejarah yang tidak dipakai sebagai nama tidak kapital (kemerdekaan).", "lvl": 2, "code": null, "src": "modul", "id": "P02-017"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan satuan ukuran yang berasal dari nama orang yang benar adalah…", "opts": ["mesin diesel, 25 volt, 10 ampere", "mesin Diesel, 25 Volt, 10 Ampere", "Mesin diesel, 25 Volt, 10 ampere", "mesin diesel, 25 Volt, 10 Ampere"], "ans": 0, "why": "Nama orang yang dipakai sebagai nama jenis atau satuan tidak ditulis kapital.", "lvl": 2, "code": null, "src": "modul", "id": "P02-018"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan nama lembaga yang benar adalah…", "opts": ["Kementerian Riset, Teknologi, dan Pendidikan Tinggi", "Kementerian Riset, Teknologi, Dan Pendidikan Tinggi", "kementerian Riset, Teknologi, dan Pendidikan Tinggi", "Kementerian riset, teknologi, dan pendidikan tinggi"], "ans": 0, "why": "Semua unsur nama resmi lembaga kapital kecuali kata tugas seperti 'dan'.", "lvl": 1, "code": null, "src": "modul", "id": "P02-019"}, {"p": "P02", "tag": "huruf", "type": "mcq", "q": "Huruf miring dipakai untuk…", "opts": ["nama ilmiah seperti Nigella sativa", "judul bab dalam skripsi", "daftar isi", "nama orang"], "ans": 0, "why": "Huruf miring: judul buku/majalah/koran yang dikutip, penegasan, nama ilmiah, dan ungkapan asing.", "lvl": 1, "code": null, "src": "modul", "id": "P02-020"}, {"p": "P02", "tag": "huruf", "type": "mcq", "q": "Huruf tebal dalam cetakan dipakai untuk menulis…", "opts": ["judul bab, daftar isi, dan lampiran", "nama ilmiah", "istilah asing", "judul koran yang dikutip"], "ans": 0, "why": "Huruf tebal: judul buku, bab, bagian bab, daftar isi, daftar tabel, daftar pustaka, indeks, lampiran.", "lvl": 1, "code": null, "src": "modul", "id": "P02-021"}, {"p": "P02", "tag": "huruf", "type": "mcq", "q": "Dalam tulisan tangan atau ketikan, kata yang seharusnya dicetak miring ditandai dengan…", "opts": ["garis bawah", "huruf kapital semua", "tanda petik tunggal", "tanda kurung"], "ans": 0, "why": "Catatan EYD: dalam tulisan tangan/ketikan, huruf yang akan dicetak miring diberi garis bawah.", "lvl": 2, "code": null, "src": "modul", "id": "P02-022"}, {"p": "P02", "tag": "kapital", "type": "tf", "q": "Kata 'Anda' yang dipakai dalam penyapaan selalu diawali huruf kapital.", "opts": null, "ans": 1, "why": "Aturan kapital no. 15: Anda dalam penyapaan ditulis kapital.", "lvl": 1, "code": null, "src": "modul", "id": "P02-023"}, {"p": "P02", "tag": "kapital", "type": "tf", "q": "Nama bulan dan hari raya ditulis dengan huruf kapital, misalnya bulan Ramadan dan hari Natal.", "opts": null, "ans": 1, "why": "Nama tahun, bulan, hari, dan hari raya diawali kapital; kata 'bulan' dan 'hari' tidak.", "lvl": 1, "code": null, "src": "modul", "id": "P02-024"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan tanda titik yang benar adalah…", "opts": ["Lihat halaman 47564 dan seterusnya.", "Lihat halaman 47.564 dan seterusnya.", "Desa itu berpenduduk 23500 jiwa.", "Bentuk dan Kebudayaan."], "ans": 0, "why": "Titik tidak dipakai pada bilangan yang tidak menyatakan jumlah (nomor halaman) dan pada akhir judul. Jumlah penduduk memakai titik: 23.500.", "lvl": 1, "code": null, "src": "modul", "id": "P02-025"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan koma yang benar adalah…", "opts": ["Jika hari ini hujan, saya tidak akan datang.", "Saya tidak akan datang, jika hari ini hujan.", "Jika hari ini hujan saya, tidak akan datang.", "Saya, tidak akan datang jika hari ini hujan."], "ans": 0, "why": "Koma dipakai setelah anak kalimat yang mendahului induk kalimat; tidak dipakai jika anak kalimat di belakang.", "lvl": 1, "code": null, "src": "modul", "id": "P02-026"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan koma yang benar adalah…", "opts": ["Saya ingin datang, tetapi hari ini hujan.", "Saya ingin datang tetapi, hari ini hujan.", "Saya ingin datang tetapi hari ini hujan.", "Saya, ingin datang tetapi hari ini hujan."], "ans": 0, "why": "Koma dipakai sebelum konjungsi pertentangan tetapi, melainkan, sedangkan.", "lvl": 1, "code": null, "src": "modul", "id": "P02-027"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan nama dan gelar akademik yang benar adalah…", "opts": ["Embun Pagi, S.E.", "Embun Pagi S.E.", "Embun Pagi, SE", "Embun Pagi. S.E"], "ans": 0, "why": "Koma dipakai di antara nama orang dan gelar akademik yang mengikutinya; gelar ditulis dengan titik.", "lvl": 1, "code": null, "src": "modul", "id": "P02-028"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan waktu yang benar adalah…", "opts": ["pukul 1.35.20", "pukul 1,35,20", "pukul 1;35;20", "pukul 1’35’20"], "ans": 0, "why": "Titik (atau titik dua) memisahkan jam, menit, detik.", "lvl": 1, "code": null, "src": "modul", "id": "P02-029"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan yang benar adalah…", "opts": ["Oleh karena itu, kita harus berhati-hati.", "Oleh karena itu kita, harus berhati-hati.", "Oleh karena itu; kita harus berhati-hati.", "Oleh karena, itu kita harus berhati-hati."], "ans": 0, "why": "Koma dipakai di belakang ungkapan penghubung antarkalimat di awal kalimat.", "lvl": 1, "code": null, "src": "modul", "id": "P02-030"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Tanda koma TIDAK dipakai sebelum kata…", "opts": ["bahwa", "tetapi", "melainkan", "sedangkan"], "ans": 0, "why": "'mengatakan, bahwa' salah; 'mengatakan bahwa' benar. Koma dipakai sebelum tetapi/melainkan/sedangkan.", "lvl": 2, "code": null, "src": "modul", "id": "P02-031"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penggunaan titik koma yang benar adalah…", "opts": ["Ayah mengurus kebun; ibu sibuk memasak di dapur.", "Ayah mengurus kebun; dan ibu sibuk memasak.", "Karena hujan; ayah tidak berangkat.", "Ayah; ibu; dan adik pergi ke pasar."], "ans": 0, "why": "Titik koma memisahkan klausa setara dalam kalimat majemuk, menggantikan kata penghubung.", "lvl": 1, "code": null, "src": "modul", "id": "P02-032"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penggunaan titik dua yang benar adalah…", "opts": ["Kita memerlukan perabot: kursi, meja, dan lemari.", "Kita memerlukan: kursi, meja, dan lemari.", "Kita memerlukan kursi: meja, dan lemari.", "Kita: memerlukan kursi, meja, dan lemari."], "ans": 0, "why": "Titik dua dipakai setelah pernyataan lengkap yang diikuti perincian; tidak dipakai jika perincian menjadi pelengkap kalimat.", "lvl": 1, "code": null, "src": "modul", "id": "P02-033"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan tanda hubung yang benar adalah…", "opts": ["se-Indonesia, ke-2, tahun 90-an, ber-KTP", "seIndonesia, ke 2, tahun 90an, berKTP", "se-indonesia, ke-dua, tahun 90 an, ber-KTP", "se Indonesia, ke-2, tahun 90-an, berKTP"], "ans": 0, "why": "Tanda hubung merangkai se- dengan kata berkapital, ke- dengan angka, angka dengan -an, dan singkatan kapital dengan imbuhan.", "lvl": 1, "code": null, "src": "modul", "id": "P02-034"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Tanda pisah (—) dipakai dalam…", "opts": ["Jakarta—Bandung (berarti 'sampai')", "anak—anak (kata ulang)", "ber—KTP", "se—Indonesia"], "ans": 0, "why": "Tanda pisah dipakai di antara bilangan/tanggal/tempat dengan arti 'sampai ke', dan untuk mengapit keterangan sisipan.", "lvl": 1, "code": null, "src": "modul", "id": "P02-035"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan rujukan sumber yang benar adalah…", "opts": ["(Fishman, 1974; Moeliono, 1985)", "(Fishman, 1974, Moeliono, 1985)", "(Fishman: 1974; Moeliono: 1985)", "(Fishman 1974. Moeliono 1985)"], "ans": 0, "why": "Titik koma memisahkan beberapa sumber kutipan.", "lvl": 2, "code": null, "src": "modul", "id": "P02-036"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Tanda garis miring yang benar dipakai pada…", "opts": ["Nomor: 125/PANSEL/OSIS/VIII/2016", "anak/anak", "Jakarta/Bandung (arti sampai)", "se/Indonesia"], "ans": 0, "why": "Garis miring: nomor surat, alamat, pengganti kata dan/atau/tiap (Rp150.000/meter).", "lvl": 1, "code": null, "src": "modul", "id": "P02-037"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan singkatan yang benar adalah…", "opts": ["dr. (dokter), Dr. (doktor), PT (perseroan terbatas)", "Dr. (dokter), dr. (doktor), P.T. (perseroan terbatas)", "dr (dokter), DR (doktor), PT. (perseroan terbatas)", "Dr (dokter), dr. (doktor), P.T (perseroan terbatas)"], "ans": 0, "why": "Gelar disingkat dengan titik: dr. = dokter, Dr. = doktor. Singkatan huruf awal kata ditulis kapital tanpa titik: PT.", "lvl": 1, "code": null, "src": "modul", "id": "P02-038"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Singkatan yang benar untuk 'atas nama' dan 'dan seterusnya' adalah…", "opts": ["a.n. dan dst.", "an. dan dst", "a.n dan d.s.t.", "AN dan DST"], "ans": 0, "why": "Singkatan dua huruf diberi titik di tiap huruf (a.n.); lebih dari dua huruf diakhiri satu titik (dst.).", "lvl": 1, "code": null, "src": "modul", "id": "P02-039"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan akronim yang benar adalah…", "opts": ["Bulog dan iptek", "BULOG dan IPTEK", "Bulog dan Iptek", "bulog dan IPTEK"], "ans": 0, "why": "Akronim nama diri dari suku kata ditulis huruf awal kapital (Bulog); akronim bukan nama diri ditulis huruf kecil (iptek).", "lvl": 1, "code": null, "src": "modul", "id": "P02-040"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Singkatan satuan ukuran dan mata uang yang benar adalah…", "opts": ["10 km dan Rp5.000", "10 km. dan Rp.5.000", "10 Km dan Rp. 5.000", "10 KM dan RP5.000"], "ans": 0, "why": "Satuan ukuran, lambang kimia, dan mata uang tidak diikuti titik.", "lvl": 1, "code": null, "src": "modul", "id": "P02-041"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan bilangan yang benar adalah…", "opts": ["Mereka menonton drama itu sampai tiga kali.", "Mereka menonton drama itu sampai 3 kali.", "Mereka menonton drama itu sampai 3x.", "Mereka menonton drama itu sampai tiga x."], "ans": 0, "why": "Bilangan yang dapat dinyatakan dengan satu atau dua kata ditulis dengan huruf.", "lvl": 1, "code": null, "src": "modul", "id": "P02-042"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan bilangan di awal kalimat yang benar adalah…", "opts": ["Sebanyak 250 peserta mengikuti lomba.", "250 peserta mengikuti lomba.", "Dua ratus lima puluh peserta mengikuti lomba itu sebanyak.", "250 orang peserta, mengikuti lomba."], "ans": 0, "why": "Angka di awal kalimat yang lebih dari dua kata didahului kata sebanyak/sejumlah atau susunannya diubah.", "lvl": 1, "code": null, "src": "modul", "id": "P02-043"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan bilangan tingkat yang benar adalah…", "opts": ["abad ke-7, abad VII, abad ketujuh", "abad ke 7, abad ke-VII, abad ke-tujuh", "abad ke-7, abad ke-VII, abad ketujuh", "abad 7-an, abad VII, abad ketujuh"], "ans": 0, "why": "Bilangan tingkat: angka Romawi (VII), ke- + angka Arab dengan tanda hubung (ke-7), atau huruf (ketujuh). Tidak 'ke-VII'.", "lvl": 1, "code": null, "src": "modul", "id": "P02-044"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan bilangan dalam kuitansi/akta yang benar adalah…", "opts": ["Rp200.000.000,00 (dua ratus juta rupiah)", "Rp. 200.000.000,- (dua ratus juta rupiah)", "Rp 200,000,000.00 (dua ratus juta rupiah)", "200.000.000 rupiah (dua ratus juta Rp)"], "ans": 0, "why": "Angka boleh diikuti huruf; Rp tanpa titik dan spasi, ribuan dengan titik, sen dengan koma.", "lvl": 2, "code": null, "src": "modul", "id": "P02-045"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan nama geografi yang mengandung bilangan yang benar adalah…", "opts": ["Rajaampat dan Simpanglima", "Raja Ampat dan Simpang Lima", "Raja-ampat dan Simpang-lima", "Raja 4 dan Simpang 5"], "ans": 0, "why": "Bilangan sebagai unsur nama geografi ditulis serangkai dengan huruf (sesuai contoh modul).", "lvl": 3, "code": null, "src": "modul", "id": "P02-046"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan tanda baca yang benar terdapat pada kalimat…", "opts": ["Tim kami meraih juara lomba debat mahasiswa se-Jawa Timur.", "Pengungsi membawa pakaian, makanan dan dokumen penting.", "Mahasiswa diminta membaca novel 'Bumi Manusia' sebelum diskusi.", "Para pedagang menyampaikan keluhan, kepada pengelola pasar."], "ans": 0, "why": "se- + kata berhuruf kapital memakai tanda hubung (se-Jawa Timur). Opsi lain: perincian butuh koma sebelum 'dan', judul buku ditulis miring bukan dengan petik tunggal, koma sebelum 'kepada' tidak perlu.", "lvl": 1, "code": null, "src": "uts", "id": "P02-047"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "'Hingga akhir bulan agustus, badan pusat statistik mencatat inflasi tertinggi terjadi di pulau sumatra.' Perbaikan yang tepat untuk kata-kata yang salah adalah…", "opts": ["bulan Agustus, Badan Pusat Statistik, Pulau Sumatra", "Bulan Agustus, Badan pusat statistik, pulau Sumatra", "bulan Agustus, Badan Pusat Statistik, pulau Sumatra", "Bulan Agustus, Badan Pusat Statistik, Pulau Sumatra"], "ans": 0, "why": "Nama bulan kapital, kata 'bulan' tidak. Semua unsur nama lembaga resmi kapital. Unsur geografi yang diikuti nama diri kapital: Pulau Sumatra.", "lvl": 2, "code": null, "src": "uts", "id": "P02-048"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Kalimat yang penggunaan komanya SALAH adalah…", "opts": ["Kepala dinas, Rahmat Hidayat mengatakan, bahwa program itu berjalan lancar.", "Program itu berjalan lancar, tetapi anggarannya terbatas.", "Jika anggarannya cukup, program itu akan diperluas.", "Oleh karena itu, program itu perlu dievaluasi."], "ans": 0, "why": "Tidak ada koma sebelum 'bahwa'. Keterangan aposisi 'Rahmat Hidayat' juga harus diapit dua koma.", "lvl": 2, "code": null, "src": "uts", "id": "P02-049"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan bilangan yang sesuai EYD adalah…", "opts": ["Rombongan itu terdiri atas 12 dosen, 40 mahasiswa, dan 3 sopir.", "Rombongan itu terdiri atas, 12 dosen, 40 mahasiswa, dan 3 sopir.", "Rombongan itu terdiri atas dua belas dosen, 40 mahasiswa, dan tiga sopir.", "Rombongan itu terdiri atas, dua belas dosen, empat puluh mahasiswa, tiga sopir."], "ans": 0, "why": "Bilangan dalam perincian berurutan ditulis dengan angka secara konsisten, dan tidak ada koma setelah 'atas'.", "lvl": 2, "code": null, "src": "uts", "id": "P02-050"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penggunaan tanda kurung yang benar terdapat pada kalimat…", "opts": ["KPK (Komisi Pemberantasan Korupsi) menetapkan dua tersangka baru.", "Anggota DPR (Dewan perwakilan rakyat) menolak usulan itu.", "Ia akan berangkat ke Medan (besok pagi).", "Semua (mahasiswa) wajib hadir."], "ans": 0, "why": "Tanda kurung mengapit kepanjangan singkatan atau keterangan tambahan. Kepanjangan nama lembaga ditulis kapital di setiap unsurnya.", "lvl": 1, "code": null, "src": "uts", "id": "P02-051"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "'Desa itu terletak di Kaki selatan gunung Slamet, pada ketinggian 800 meter di atas permukaan Laut.' Perbaikan huruf kapital yang tepat adalah…", "opts": ["Desa itu terletak di kaki selatan Gunung Slamet, pada ketinggian 800 meter di atas permukaan laut.", "Desa itu terletak di kaki Selatan Gunung Slamet, pada ketinggian 800 meter di atas permukaan laut.", "Desa itu terletak di kaki selatan gunung Slamet, pada ketinggian 800 meter di atas permukaan Laut.", "Desa itu terletak di Kaki Selatan Gunung Slamet, pada ketinggian 800 meter di atas permukaan Laut."], "ans": 0, "why": "Gunung kapital karena diikuti nama diri (Gunung Slamet). 'kaki', 'selatan', dan 'laut' bukan nama diri.", "lvl": 1, "code": null, "src": "uts", "id": "P02-052"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "'Setiap Jumat diadakan rapat koordinasi fakultas.' Bila 'rapat koordinasi' dijadikan akronim, penulisan yang benar adalah…", "opts": ["rakor", "Rakor", "RAKOR", "ra-kor"], "ans": 0, "why": "Akronim yang bukan nama diri ditulis dengan huruf kecil semua: rakor (seperti rapim, iptek).", "lvl": 2, "code": null, "src": "uts", "id": "P02-053"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "'Harga tiket itu dua ratus lima puluh ribu rupiah.' Bila ditulis dengan angka, penulisan yang benar adalah…", "opts": ["Rp250.000,00", "Rp.250.000,-", "Rp 250.000,-", "Rp.250.000"], "ans": 0, "why": "Lambang Rp tanpa titik dan tanpa spasi; ribuan dipisah titik; sen ditulis ,00 (bukan ,-).", "lvl": 1, "code": null, "src": "uts", "id": "P02-054"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan nama dan gelar akademik yang benar adalah…", "opts": ["Rapat dipimpin oleh Dr. Siti Aminah, M.Pd.", "Rapat dipimpin oleh Dr. Siti Aminah. M.Pd.", "Rapat dipimpin oleh DR. Siti Aminah, MPd.", "Rapat dipimpin oleh Dr Siti Aminah M.Pd"], "ans": 0, "why": "Gelar di belakang nama dipisahkan koma dan setiap unsur singkatan gelar diberi titik (M.Pd.).", "lvl": 1, "code": null, "src": "uts", "id": "P02-055"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan huruf kapital yang benar terdapat pada kalimat…", "opts": ["Ketertarikan bangsa Jepang mempelajari bahasa Indonesia terus meningkat.", "Pemerintah memberi Beasiswa kepada mahasiswa berprestasi.", "Ia menikah dengan gadis dari Suku Minang.", "Kita bersyukur kepada Tuhan yang Maha Pengasih."], "ans": 0, "why": "Kata 'bangsa' dan 'suku' tidak kapital, nama bangsanya kapital (bangsa Jepang). 'beasiswa' bukan nama diri. Sebutan Tuhan: Tuhan Yang Maha Pengasih.", "lvl": 2, "code": null, "src": "uts", "id": "P02-056"}, {"p": "P02", "tag": "kata", "type": "mcq", "q": "Penulisan kata berimbuhan dan gabungan kata yang semuanya benar adalah…", "opts": ["nonformal, tunanetra, ultrasonik, multifungsi", "non formal, tuna netra, ultra sonik, multi fungsi", "pra pemilu, pasca bencana, swalayan, asusila", "pascapanen, purna tugas, swadaya, semi permanen"], "ans": 0, "why": "Imbuhan asing/daerah ditulis serangkai: nonformal, tunanetra, prapemilu, pascabencana, purnatugas, semipermanen.", "lvl": 1, "code": null, "src": "uts", "id": "P02-057"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan judul buku yang benar adalah…", "opts": ["Saya sedang membaca buku Laskar Pelangi karya Andrea Hirata.", "Saya sedang membaca buku laskar pelangi karya Andrea Hirata.", "Saya sedang membaca Buku Laskar Pelangi karya andrea hirata.", "Saya sedang membaca buku Laskar pelangi karya Andrea hirata."], "ans": 0, "why": "Setiap kata judul buku dan nama orang diawali kapital; kata 'buku' tidak.", "lvl": 1, "code": null, "src": "uts", "id": "P02-058"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan petikan langsung yang benar adalah…", "opts": ["“Saya akan datang besok,” katanya.", "“Saya akan datang besok.”, katanya.", "“Saya akan datang besok”, katanya.", "“Saya akan datang besok.” katanya."], "ans": 0, "why": "Jika petikan langsung diikuti keterangan pengutip, tanda koma diletakkan di dalam tanda petik penutup.", "lvl": 2, "code": null, "src": "uts", "id": "P02-059"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "'Pada tahun 2000an diselenggarakan festival budaya seNusantara di Bali.' Perbaikan yang tepat adalah…", "opts": ["Pada tahun 2000-an diselenggarakan festival budaya se-Nusantara di Bali.", "Pada tahun 2000 an diselenggarakan festival budaya se Nusantara di Bali.", "Pada tahun 2000-an di selenggarakan festival budaya se-Nusantara di Bali.", "Pada tahun 2000an diselenggarakan festival budaya se-nusantara di Bali."], "ans": 0, "why": "Angka + -an dan se- + kapital memakai tanda hubung; di- sebagai awalan ditulis serangkai.", "lvl": 1, "code": null, "src": "uts", "id": "P02-060"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan kalimat yang sesuai EYD adalah…", "opts": ["Ia tidak sedang tidur, tetapi sedang membaca.", "Ia tidak sedang tidur tetapi sedang membaca.", "Ia tidak sedang tidur, melainkan sedang membaca.", "Ia tidak sedang tidur melainkan sedang membaca."], "ans": 0, "why": "Pola pasangan: 'tidak ... tetapi' (menyangkal verba/adjektiva) dan 'bukan ... melainkan' (menyangkal nomina). Koma diletakkan sebelum 'tetapi'.", "lvl": 3, "code": null, "src": "uts", "id": "P02-061"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "(1) Kabupaten Sleman masuk wilayah Daerah Istimewa Yogyakarta. (2) Secara geografis, wilayahnya berada di lereng Gunung Merapi. (3) Luasnya sekitar 574,82 km2. (4) Sleman terbagi menjadi tujuh belas Kecamatan. (5) Ibu kotanya berada di Kecamatan Sleman. Kesalahan huruf kapital terdapat pada kalimat…", "opts": ["(4)", "(1)", "(2)", "(5)"], "ans": 0, "why": "'kecamatan' di kalimat (4) tidak diikuti nama diri, jadi tidak kapital. Di kalimat (5) 'Kecamatan Sleman' sudah benar.", "lvl": 2, "code": null, "src": "uts", "id": "P02-062"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penulisan tanda baca yang benar adalah…", "opts": ["Kadar gula darah normal berkisar antara 70 hingga 140 mg/dL.", "Untuk konsultasi, hubungi Rina Lestari, SKep. Ns.", "Operasi itu berlangsung selama 02;15;30.", "Obat diminum pukul 07’00 WIB."], "ans": 0, "why": "Opsi lain salah: gelar ditulis S.Kep., Ns.; jangka waktu pakai titik (2.15.30); jam pakai titik (07.00).", "lvl": 2, "code": null, "src": "uts", "id": "P02-063"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Penggunaan tanda baca yang benar adalah…", "opts": ["Ia menyelesaikan maraton itu dalam waktu 3.42.15.", "Indonesia memiliki sekitar 17,000 pulau.", "Lestari, Dewi. 2019. Gizi Seimbang. Bandung, Pustaka Kita.", "Ia menyetor uang sebanyak Rp.750.000,00."], "ans": 0, "why": "Titik memisahkan jam, menit, detik pada jangka waktu. Ribuan pakai titik (17.000); kota dan penerbit dipisah titik dua; Rp tanpa titik.", "lvl": 2, "code": null, "src": "uts", "id": "P02-064"}, {"p": "P02", "tag": "kata", "type": "mcq", "q": "Penggunaan tanda hubung yang benar adalah…", "opts": ["Kelompok kami meraih peringkat ke-2 dalam lomba itu.", "Kelompok kami meraih peringkat ke-II dalam lomba itu.", "Kelompok kami meraih peringkat ke dua dalam lomba itu.", "Pendakian dilakukan pada 5-8 Mei dari Basecamp-Puncak."], "ans": 0, "why": "ke- + angka Arab memakai tanda hubung (ke-2); angka Romawi tidak didahului ke-. Rentang tanggal/tempat memakai tanda pisah (—).", "lvl": 1, "code": null, "src": "uts", "id": "P02-065"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "Penulisan huruf kapital yang benar adalah…", "opts": ["Sebagian besar penduduk pulau itu adalah suku Bugis.", "Upacara bendera dilaksanakan pada hari senin.", "Gubernur menemui Presiden di istana negara.", "Peringatan itu jatuh pada bulan ramadhan."], "ans": 0, "why": "Nama suku kapital, kata 'suku' tidak. Nama hari dan bulan kapital (Senin, Ramadan). Istana Negara adalah nama diri.", "lvl": 1, "code": null, "src": "uts", "id": "P02-066"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan angka yang benar adalah…", "opts": ["Peserta seminar hari ini mencapai 85 orang.", "Dari 40 peserta, 25 orang lulus, lima belas orang gagal.", "Dua puluh tujuh naskah kuno itu sejumlah tersimpan di museum.", "12 orang terluka dalam kecelakaan itu."], "ans": 0, "why": "Bilangan lebih dari dua kata boleh ditulis angka di tengah kalimat. Perincian harus konsisten angka; angka tidak boleh di awal kalimat.", "lvl": 2, "code": null, "src": "uts", "id": "P02-067"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan bilangan yang benar adalah…", "opts": ["Ia membeli dua ekor ayam dan tiga ekor bebek.", "Ia membeli dua ekor ayam dan 3 bebek.", "Ia membeli 2 ekor ayam dan tiga ekor bebek.", "Ia membeli 2 ayam dan 3 bebek."], "ans": 0, "why": "Bilangan yang dapat ditulis dengan satu atau dua kata ditulis dengan huruf, dan penulisannya konsisten.", "lvl": 1, "code": null, "src": "uts", "id": "P02-068"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "'Rafflesia: salah satu bunga terbesar di dunia tumbuh di hutan Sumatra.' Perbaikan tanda baca yang tepat adalah…", "opts": ["Rafflesia—salah satu bunga terbesar di dunia—tumbuh di hutan Sumatra.", "Rafflesia-salah satu bunga terbesar di dunia-tumbuh di hutan Sumatra.", "Rafflesia, salah satu bunga terbesar di dunia tumbuh di hutan Sumatra.", "Rafflesia; salah satu bunga terbesar di dunia; tumbuh di hutan Sumatra."], "ans": 0, "why": "Keterangan aposisi/sisipan diapit tanda pisah (—) atau dua koma, bukan tanda hubung.", "lvl": 2, "code": null, "src": "uts", "id": "P02-069"}, {"p": "P02", "tag": "kapital", "type": "mcq", "q": "'raden ajeng kartini yang lahir di jepara dikenal sebagai pelopor emansipasi wanita.' Penulisan kapital yang tepat adalah…", "opts": ["Raden Ajeng Kartini yang lahir di Jepara dikenal sebagai pelopor emansipasi wanita.", "Raden ajeng Kartini yang lahir di Jepara dikenal sebagai Pelopor Emansipasi Wanita.", "raden Ajeng Kartini yang lahir di Jepara dikenal sebagai pelopor emansipasi wanita.", "Raden Ajeng Kartini yang lahir di jepara dikenal sebagai Pelopor emansipasi wanita."], "ans": 0, "why": "Gelar keturunan yang diikuti nama orang kapital (Raden Ajeng), nama tempat kapital, 'pelopor emansipasi' bukan nama diri.", "lvl": 1, "code": null, "src": "uts", "id": "P02-070"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan bilangan yang benar adalah…", "opts": ["Ia sudah mencoba resep itu sebanyak empat kali.", "Ia sudah mencoba resep itu sebanyak 4 kali.", "Ia sudah mencoba resep itu sebanyak 4x.", "Koleksi sepatunya berjumlah dua puluh tujuh pasang lebih dari 1000."], "ans": 0, "why": "Bilangan satu kata ditulis dengan huruf; jangan pakai 'x' untuk 'kali'.", "lvl": 1, "code": null, "src": "uts", "id": "P02-071"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Pemakaian tanda titik koma yang benar adalah…", "opts": ["Kakak menyusun laporan; adik menggambar di kamarnya.", "Rapat ditunda; karena ketua sakit.", "Oleh karena itu; kita harus bersiap.", "Karena hujan deras; pertandingan dihentikan."], "ans": 0, "why": "Titik koma memisahkan dua klausa setara tanpa kata penghubung. Tidak dipakai sebelum 'karena' atau setelah ungkapan penghubung.", "lvl": 1, "code": null, "src": "uts", "id": "P02-072"}, {"p": "P02", "tag": "angka", "type": "mcq", "q": "Penulisan singkatan yang benar adalah…", "opts": ["Mahasiswa Universitas Gadjah Mada (UGM) mengikuti seleksi itu.", "Vaksinasi dilakukan di PUSKESMAS kecamatan.", "Kemajuan IPTEK mengubah dunia kerja.", "Perum BULOG menjaga harga beras."], "ans": 0, "why": "Singkatan huruf awal ditulis kapital (UGM). Akronim nama diri dari suku kata ditulis huruf awal kapital (Puskesmas, Bulog); akronim bukan nama diri huruf kecil (iptek).", "lvl": 2, "code": null, "src": "uts", "id": "P02-073"}, {"p": "P02", "tag": "tandabaca", "type": "mcq", "q": "Kalimat yang paling tepat dari segi struktur dan tanda baca adalah…", "opts": ["Kami menyiapkan tenda, matras, dan senter.", "Kami menyiapkan: tenda, matras, dan senter.", "Kami menyiapkan, tenda, matras, dan senter.", "Kami menyiapkan tenda; matras; dan senter."], "ans": 0, "why": "Perincian yang menjadi objek tidak didahului titik dua atau koma; unsur perincian dipisah koma.", "lvl": 1, "code": null, "src": "uts", "id": "P02-074"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Kata telunjuk terbentuk melalui proses…", "opts": ["Infiksasi (sisipan -el-)", "Prefiksasi", "Sufiksasi", "Konfiksasi", "Reduplikasi"], "ans": 0, "why": "Sisipan -el- + tunjuk.", "lvl": 1, "code": null, "src": "modul", "id": "P04-001"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Bentuk berimbuhan me- + produksi yang benar adalah…", "opts": ["memproduksi", "memroduksi", "mempoduksi", "menproduksi", "memeproduksi"], "ans": 0, "why": "Gugus konsonan pr- tidak luluh: memproduksi.", "lvl": 2, "code": null, "src": "modul", "id": "P04-002"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Bentuk berimbuhan me- + sapu yang benar adalah…", "opts": ["menyapu", "mensapu", "menapu", "menyyapu", "meyapu"], "ans": 0, "why": "Huruf s luluh menjadi ny: menyapu.", "lvl": 1, "code": null, "src": "modul", "id": "P04-003"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Penulisan imbuhan asing yang benar adalah…", "opts": ["antivirus, nonformal, pascasarjana", "anti virus, non formal, pasca sarjana", "anti-virus, non-formal, pasca-sarjana", "antiVirus, nonFormal, pascaSarjana", "anti virus, nonformal, pasca-sarjana"], "ans": 0, "why": "Imbuhan asing/terikat ditulis serangkai.", "lvl": 1, "code": null, "src": "modul", "id": "P04-004"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kata baku yang benar adalah…", "opts": ["kreativitas, teknologi, modern", "kreatifitas, tehnologi, moderen", "kreativitas, tehnologi, moderen", "kreatifitas, teknologi, modern", "kretivitas, teknologi, modren"], "ans": 0, "why": "Bentuk baku: kreativitas, teknologi, modern.", "lvl": 1, "code": null, "src": "modul", "id": "P04-005"}, {"p": "P04", "tag": "diksi", "type": "mcq", "q": "Makna kata yang mengandung nilai rasa disebut makna…", "opts": ["Konotasi", "Denotasi", "Leksikal", "Gramatikal", "Referensial"], "ans": 0, "why": "Denotasi = makna sebenarnya; konotasi = nilai rasa.", "lvl": 1, "code": null, "src": "modul", "id": "P04-006"}, {"p": "P04", "tag": "diksi", "type": "mcq", "q": "Kata 'kursi' dalam kalimat 'Partai itu berebut kursi di DPR' bermakna…", "opts": ["Konotasi (jabatan)", "Denotasi (tempat duduk)", "Leksikal", "Gramatikal murni", "Istilah teknis"], "ans": 0, "why": "Kursi berarti kedudukan/jabatan.", "lvl": 2, "code": null, "src": "modul", "id": "P04-007"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kata 'supermarket' dan 'plaza' masuk ke bahasa Indonesia melalui cara…", "opts": ["adopsi", "adaptasi", "penerjemahan", "kreasi"], "ans": 0, "why": "Adopsi: bentuk dan makna kata asing diambil secara keseluruhan.", "lvl": 1, "code": null, "src": "modul", "id": "P04-008"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Pluralization → pluralisasi adalah contoh penyerapan melalui…", "opts": ["adaptasi", "adopsi", "penerjemahan", "kreasi"], "ans": 0, "why": "Adaptasi: makna diambil, ejaan disesuaikan dengan bahasa Indonesia.", "lvl": 1, "code": null, "src": "modul", "id": "P04-009"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Try out → uji coba dan overlap → tumpang tindih adalah contoh…", "opts": ["penerjemahan", "adopsi", "adaptasi", "kreasi"], "ans": 0, "why": "Penerjemahan: konsep asing dicari padanannya dalam bahasa Indonesia.", "lvl": 1, "code": null, "src": "modul", "id": "P04-010"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Spare parts → suku cadang dan effective → berhasil guna adalah contoh…", "opts": ["kreasi", "adopsi", "adaptasi", "penerjemahan"], "ans": 0, "why": "Kreasi mirip penerjemahan, tetapi tidak menuntut kesamaan bentuk kata; hanya konsep dasarnya yang diambil.", "lvl": 2, "code": null, "src": "modul", "id": "P04-011"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kata 'reshuffle' yang pengucapannya masih mengikuti cara asing termasuk unsur pinjaman yang…", "opts": ["belum sepenuhnya terserap", "sudah disesuaikan dengan kaidah", "merupakan hasil kreasi", "merupakan hasil penerjemahan"], "ans": 0, "why": "Unsur seperti reshuffle dan shuttle cock dipakai dalam bahasa Indonesia tetapi lafalnya masih asing.", "lvl": 2, "code": null, "src": "modul", "id": "P04-012"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Imbuhan yang mengapit kata dasar, seperti ke-an pada 'keadilan', disebut…", "opts": ["konfiks", "prefiks", "infiks", "sufiks"], "ans": 0, "why": "Konfiks adalah gabungan imbuhan di awal dan akhir yang membentuk satu arti.", "lvl": 1, "code": null, "src": "modul", "id": "P04-013"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Berikut yang termasuk imbuhan daerah/Sanskerta adalah…", "opts": ["tuna-, swa-, pasca-", "multi-, anti-, semi-", "-isasi, -is, non-", "infra-, ultra-, ekstra-"], "ans": 0, "why": "Imbuhan daerah/Sanskerta: tuna-, nara-, pasca-, swa-, panca-, dasa-, sapta-, catur-, maha-, antar-.", "lvl": 1, "code": null, "src": "modul", "id": "P04-014"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Penulisan kata berimbuhan yang benar adalah…", "opts": ["semipermanen, nonformal, swadaya", "semi permanen, non formal, swa daya", "semi-permanen, non-formal, swa-daya", "semipermanen, non-formal, swadaya"], "ans": 0, "why": "Imbuhan asing dan daerah ditulis serangkai dengan kata yang mengikutinya.", "lvl": 1, "code": null, "src": "modul", "id": "P04-015"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Penulisan yang benar adalah…", "opts": ["non-Indonesia", "nonIndonesia", "non Indonesia", "Non-indonesia"], "ans": 0, "why": "Jika bentuk terikat diikuti kata berhuruf awal kapital, dipakai tanda hubung (non-Indonesia, pan-Afrikanisme).", "lvl": 3, "code": null, "src": "modul", "id": "P04-016"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Bentuk meN- + konsumsi yang benar adalah…", "opts": ["mengonsumsi", "mengkonsumsi", "menkonsumsi", "mekonsumsi"], "ans": 0, "why": "Huruf awal K luluh bila bertemu meN-: mengonsumsi.", "lvl": 1, "code": null, "src": "modul", "id": "P04-017"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Bentuk meN- + kritik yang benar adalah…", "opts": ["mengkritik", "mengritik", "menkritik", "merkritik"], "ans": 0, "why": "Kata dasar diawali gugus konsonan (kr-) tidak luluh: mengkritik.", "lvl": 1, "code": null, "src": "modul", "id": "P04-018"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Bentuk peN- + protes yang dicontohkan modul sebagai pengecualian adalah…", "opts": ["pemrotes", "pemprotes", "penprotes", "peprotes"], "ans": 0, "why": "Protes diawali gugus 'pr' sehingga seharusnya tidak luluh, tetapi 'pemrotes' adalah bentuk pengecualian.", "lvl": 3, "code": null, "src": "modul", "id": "P04-019"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Kelompok kata yang semuanya benar adalah…", "opts": ["menyurvei, menelaah, memelihara", "mensurvei, mentelaah, mempelihara", "menyurvei, mentelaah, memelihara", "mensurvei, menelaah, mempelihara"], "ans": 0, "why": "Huruf awal S, T, P luluh: menyurvei, menelaah, memelihara.", "lvl": 2, "code": null, "src": "modul", "id": "P04-020"}, {"p": "P04", "tag": "diksi", "type": "mcq", "q": "Makna kata menurut kamus disebut makna…", "opts": ["leksikal", "gramatikal", "konotasi", "kontekstual"], "ans": 0, "why": "Leksikal = makna kamus; gramatikal = makna menurut bentuk/konteks gramatikal.", "lvl": 1, "code": null, "src": "modul", "id": "P04-021"}, {"p": "P04", "tag": "diksi", "type": "mcq", "q": "Kalimat yang memakai kata yang lazim adalah…", "opts": ["Ratna jatuh dari tangga.", "Ratna tumbang dari tangga.", "Kucing kesayangan Shinta wafat.", "Dies natalis Mitha dirayakan di panti asuhan."], "ans": 0, "why": "Kata lazim tidak menimbulkan makna janggal. 'Tumbang', 'wafat' (untuk kucing), 'dies natalis' (untuk orang) tidak lazim.", "lvl": 1, "code": null, "src": "modul", "id": "P04-022"}, {"p": "P04", "tag": "diksi", "type": "mcq", "q": "Kata 'melihat' memiliki kata khusus seperti menengok, melirik, mengintip. Hubungan ini disebut…", "opts": ["kata umum dan kata khusus", "sinonim", "antonim", "homonim"], "ans": 0, "why": "Melihat adalah kata umum; menengok, melirik, dll. adalah kata khusus.", "lvl": 2, "code": null, "src": "modul", "id": "P04-023"}, {"p": "P04", "tag": "diksi", "type": "mcq", "q": "Pasangan kata yang mirip tetapi berbeda makna dicontohkan modul dengan…", "opts": ["intensif – insentif", "benar – betul", "kencing – ke belakang", "efektif – berhasil guna"], "ans": 0, "why": "Intensif (sungguh-sungguh) dan insentif (tambahan penghasilan) adalah kata yang mirip.", "lvl": 2, "code": null, "src": "modul", "id": "P04-024"}, {"p": "P04", "tag": "diksi", "type": "mcq", "q": "Bentuk yang hemat adalah…", "opts": ["agar", "agar supaya", "agar supaya untuk", "supaya agar"], "ans": 0, "why": "Agar dan supaya bersinonim; cukup salah satu.", "lvl": 1, "code": null, "src": "modul", "id": "P04-025"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata baku adalah…", "opts": ["antre, apotek, atlet, izin", "antri, apotik, atlit, ijin", "antre, apotik, atlet, ijin", "antri, apotek, atlit, izin"], "ans": 0, "why": "Baku: antre, apotek, atlet, izin.", "lvl": 1, "code": null, "src": "modul", "id": "P04-026"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata baku adalah…", "opts": ["jadwal, kualitas, kuitansi, miliar", "jadual, kwalitas, kwitansi, milyar", "jadwal, kwalitas, kuitansi, milyar", "jadual, kualitas, kwitansi, miliar"], "ans": 0, "why": "Baku: jadwal, kualitas, kuitansi, miliar.", "lvl": 1, "code": null, "src": "modul", "id": "P04-027"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata baku adalah…", "opts": ["nasihat, objek, praktik, risiko", "nasehat, obyek, praktek, resiko", "nasihat, obyek, praktik, resiko", "nasehat, objek, praktek, risiko"], "ans": 0, "why": "Baku: nasihat, objek, praktik, risiko.", "lvl": 1, "code": null, "src": "modul", "id": "P04-028"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata baku adalah…", "opts": ["silakan, telantar, imbau, embus", "silahkan, terlantar, himbau, hembus", "silakan, terlantar, imbau, hembus", "silahkan, telantar, himbau, embus"], "ans": 0, "why": "Baku: silakan, telantar, imbau, embus.", "lvl": 2, "code": null, "src": "modul", "id": "P04-029"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kata baku dari 'merubah' adalah…", "opts": ["mengubah", "merobah", "merubahkan", "mengrubah"], "ans": 0, "why": "Kata dasarnya 'ubah' (rubah = hewan), jadi meN- + ubah = mengubah.", "lvl": 1, "code": null, "src": "modul", "id": "P04-030"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Bentuk baku dari 'meminimalisir' adalah…", "opts": ["meminimalkan", "meminimalisirkan", "meminimumkan", "minimalisir"], "ans": 0, "why": "Tabel kata baku modul: meminimalisir → meminimalkan.", "lvl": 2, "code": null, "src": "modul", "id": "P04-031"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "Penulisan kata yang SALAH terdapat pada kalimat…", "opts": ["Warga desa membangun balai pertemuan secara swadaya.", "Para tunakarya di kota itu mendapat pelatihan menjahit.", "Setiap truk antarkota wajib lulus uji laik jalan.", "Banyak para relawan melakukan kerjabakti di bantaran sungai."], "ans": 3, "why": "'kerjabakti' seharusnya 'kerja bakti' (gabungan kata ditulis terpisah), dan 'banyak para' boros karena keduanya bermakna jamak. swadaya, tunakarya, antarkota ditulis serangkai.", "lvl": 2, "code": null, "src": "uts", "id": "P04-032"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kalimat yang penulisan imbuhannya sesuai EYD adalah…", "opts": ["Negara-negara antiterorisme menandatangani perjanjian multilateral.", "Negara-negara anti-terorisme menandatangani perjanjian multilateral.", "Negara-negara antiterorisme menandatangani perjanjian multi-lateral.", "Negara-negara anti terorisme menandatangani perjanjian multi lateral."], "ans": 0, "why": "Imbuhan asing anti- dan multi- ditulis serangkai dengan kata dasarnya.", "lvl": 1, "code": null, "src": "uts", "id": "P04-033"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "'Pemerintah mempercepat pembangunan jalan tol di luar Jawa.' Imbuhan pe-an pada 'pembangunan' bermakna sama dengan imbuhan pe-an pada kata…", "opts": ["penanaman", "perumahan", "pelabuhan", "pertokoan"], "ans": 0, "why": "pembangunan = proses membangun; penanaman = proses menanam. Perumahan, pertokoan = kumpulan/tempat; pelabuhan = tempat berlabuh.", "lvl": 2, "code": null, "src": "uts", "id": "P04-034"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Penulisan kata yang benar terdapat pada kalimat…", "opts": ["Data itu telah diubah dan disalahgunakan oleh oknum.", "Data itu telah dirubah dan disalahgunakan oleh oknum.", "Data itu telah diubah dan disalah gunakan oleh oknum.", "Data itu telah dirubah dan di salahgunakan oleh oknum."], "ans": 0, "why": "Kata dasarnya 'ubah' (bukan rubah). Gabungan kata yang mendapat awalan dan akhiran sekaligus ditulis serangkai: disalahgunakan.", "lvl": 1, "code": null, "src": "uts", "id": "P04-035"}, {"p": "P04", "tag": "imbuhan", "type": "mcq", "q": "'Tim itu menempati posisi teratas klasemen.' Imbuhan me-i pada 'menempati' bermakna sama dengan imbuhan me-i pada kalimat…", "opts": ["Partai itu menduduki kursi terbanyak di parlemen.", "Ibu menggarami sayur sebelum disajikan.", "Anak-anak melempari mangga dengan batu.", "Guru itu menangani siswa dengan sabar."], "ans": 0, "why": "menempati = menjadikan sebagai tempat; menduduki = menjadikan sebagai tempat duduk/posisi. menggarami = memberi garam; melempari = berulang kali melempar.", "lvl": 3, "code": null, "src": "uts", "id": "P04-036"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata yang semuanya baku adalah…", "opts": ["teoretis, metode, teknik, praktik", "teoritis, metoda, tehnik, praktek", "teoretis, metoda, teknik, praktek", "teoritis, metode, tehnik, praktik"], "ans": 0, "why": "Bentuk baku: teoretis, metode, teknik, praktik.", "lvl": 1, "code": null, "src": "uts", "id": "P04-037"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "'Di era digitalisasi, mahasiswa harus punya kreatifitas tinggi dan tidak gagap tehnologi moderen.' Perbaikan kata yang salah adalah…", "opts": ["kreativitas, teknologi, modern", "kreatifitas, teknologi, modern", "kreativitas, tehnologi, modern", "kreativitas, teknologi, moderen"], "ans": 0, "why": "Bentuk baku: kreativitas (dari creativity), teknologi, modern.", "lvl": 1, "code": null, "src": "uts", "id": "P04-038"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata yang semuanya baku adalah…", "opts": ["konsekuen, kuesioner, frekuensi", "konsekwen, kuesioner, frekwensi", "konsekuen, kuisioner, frekuensi", "konsekwen, kuisioner, frekwensi"], "ans": 0, "why": "Bentuk baku: konsekuen, kuesioner, frekuensi (qu/kw diserap menjadi ku).", "lvl": 1, "code": null, "src": "uts", "id": "P04-039"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata yang semuanya baku adalah…", "opts": ["kanker, komplet, konkret, merek, miliar", "kangker, komplit, konkrit, merk, milyar", "kanker, komplit, konkret, merk, miliar", "kangker, komplet, konkrit, merek, milyar"], "ans": 0, "why": "Bentuk baku: kanker, komplet, konkret, merek, miliar.", "lvl": 1, "code": null, "src": "uts", "id": "P04-040"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "Kelompok kata yang semuanya baku adalah…", "opts": ["ijazah, sportif, kualitas, analisis, risiko", "ijasah, sportif, kwalitas, analisa, resiko", "ijazah, sportip, kualitas, analisa, risiko", "ijasah, sportif, kualitas, analisis, resiko"], "ans": 0, "why": "Bentuk baku: ijazah, sportif, kualitas, analisis, risiko.", "lvl": 1, "code": null, "src": "uts", "id": "P04-041"}, {"p": "P04", "tag": "serapan", "type": "mcq", "q": "'Di nota itu tertulis tagihan dua milyar rupiah dan sudah dilegalisir.' Perbaikan yang tepat adalah…", "opts": ["miliar, dilegalisasi", "milyar, dilegalisasi", "miliar, dilegalisir", "milyar, dilegalisir"], "ans": 0, "why": "Bentuk baku: miliar dan legalisasi (dilegalisasi).", "lvl": 1, "code": null, "src": "uts", "id": "P04-042"}, {"p": "P05", "tag": "definisi", "type": "mcq", "q": "Unsur minimal sebuah kalimat adalah…", "opts": ["Subjek dan predikat", "Subjek dan objek", "Predikat dan objek", "Subjek, predikat, objek", "Keterangan dan pelengkap"], "ans": 0, "why": "Kalimat minimal terdiri atas S dan P.", "lvl": 1, "code": null, "src": "modul", "id": "P05-001"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat 'Pembelajaran berbasis TIK adalah merupakan cara yang tepat' tidak efektif karena…", "opts": ["Pleonasme: adalah dan merupakan dipakai bersamaan", "Tidak ada subjek", "Tidak ada predikat", "Salah huruf kapital", "Kurang tanda koma"], "ans": 0, "why": "Pilih salah satu: adalah atau merupakan.", "lvl": 1, "code": null, "src": "modul", "id": "P05-002"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang efektif adalah…", "opts": ["Para mahasiswa sedang berdiskusi.", "Para mahasiswa-mahasiswa sedang berdiskusi.", "Para mahasiswa-mahasiswi sedang berdiskusi.", "Mahasiswa-mahasiswa para sedang berdiskusi.", "Para-para mahasiswa sedang berdiskusi."], "ans": 0, "why": "'Para' sudah bermakna jamak, jangan diulang.", "lvl": 1, "code": null, "src": "modul", "id": "P05-003"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Perbaikan yang tepat untuk 'Di daerah Banyumas mempromosikan wisata gunung' adalah…", "opts": ["Daerah Banyumas mempromosikan wisata gunung.", "Di daerah Banyumas dipromosikan wisata gunung oleh.", "Daerah Banyumas di promosikan wisata gunung.", "Di daerah Banyumas, mempromosikan wisata gunung.", "Banyumas di daerah mempromosikan wisata gunung."], "ans": 0, "why": "Subjek tidak boleh didahului kata depan (kesepadanan).", "lvl": 2, "code": null, "src": "modul", "id": "P05-004"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kesamaan bentuk kata dalam rincian disebut…", "opts": ["Keparalelan", "Kehematan", "Kelogisan", "Ketegasan", "Kecermatan"], "ans": 0, "why": "Contoh: pengetikan, pemeriksaan, penjilidan (sama-sama pe-an).", "lvl": 1, "code": null, "src": "modul", "id": "P05-005"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kalimat 'Kepada Bapak Rektor, waktu dan tempat kami persilakan' melanggar ciri…", "opts": ["Kelogisan", "Keparalelan", "Kehematan", "Ketegasan", "Kesepadanan"], "ans": 0, "why": "Waktu dan tempat tidak bisa dipersilakan; yang dipersilakan Bapak Rektor.", "lvl": 2, "code": null, "src": "modul", "id": "P05-006"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang tidak efektif karena tidak memiliki subjek adalah…", "opts": ["Dalam rapat itu membahas kenaikan harga BBM.", "Rapat itu membahas kenaikan harga BBM.", "Peserta rapat membahas kenaikan harga BBM.", "Kenaikan harga BBM dibahas dalam rapat itu."], "ans": 0, "why": "Preposisi 'dalam' di awal membuat 'rapat itu' menjadi keterangan, sehingga kalimat kehilangan subjek.", "lvl": 1, "code": null, "src": "modul", "id": "P05-007"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Perbaikan 'Bagi mahasiswa yang kehilangan KTM harap melapor' yang efektif adalah…", "opts": ["Mahasiswa yang kehilangan KTM harap melapor.", "Bagi mahasiswa yang kehilangan KTM, harap melapor.", "Bagi mahasiswa yang kehilangan KTM agar melapor.", "Untuk mahasiswa yang kehilangan KTM harap melapor."], "ans": 0, "why": "Hilangkan 'bagi' agar 'mahasiswa...' menjadi subjek.", "lvl": 1, "code": null, "src": "modul", "id": "P05-008"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Iqbal membeli seragam, kemudian Iqbal sekaligus membeli 10 bola.' Kalimat ini tidak efektif karena…", "opts": ["subjek diulang tanpa perlu", "tidak memiliki predikat", "maknanya ganda", "tidak logis"], "ans": 0, "why": "Subjek yang sama cukup ditulis sekali: 'Iqbal membeli seragam, sekaligus membeli 10 bola.'", "lvl": 1, "code": null, "src": "modul", "id": "P05-009"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang hemat adalah…", "opts": ["Para siswa diharapkan memahami materi.", "Para siswa-siswa diharapkan memahami materi.", "Para siswa diharapkan agar supaya memahami materi.", "Para siswa sekalian diharapkan untuk memahami materi."], "ans": 0, "why": "'Para' sudah bermakna jamak, jadi kata tidak perlu diulang; 'agar supaya' bersinonim.", "lvl": 1, "code": null, "src": "modul", "id": "P05-010"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Bentuk yang tidak hemat adalah…", "opts": ["sangat indah sekali", "sangat indah", "indah sekali", "amat indah"], "ans": 0, "why": "'Sangat' dan 'sekali' sama-sama penguat; cukup salah satu.", "lvl": 1, "code": null, "src": "modul", "id": "P05-011"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang tidak hemat adalah…", "opts": ["Mereka saling tolong-menolong satu sama lain.", "Mereka saling menolong.", "Mereka tolong-menolong.", "Mereka saling membantu."], "ans": 0, "why": "'Saling', bentuk ulang '-menolong', dan 'satu sama lain' sama-sama bermakna timbal balik.", "lvl": 1, "code": null, "src": "modul", "id": "P05-012"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kalimat yang logis adalah…", "opts": ["Untuk menghemat waktu, kami lanjutkan acara ini.", "Untuk mempersingkat waktu, kami lanjutkan acara ini.", "Untuk memperpendek waktu, kami lanjutkan acara ini.", "Untuk mempercepat waktu, kami lanjutkan acara ini."], "ans": 0, "why": "Waktu tidak bisa dipersingkat; yang bisa adalah menghemat waktu.", "lvl": 1, "code": null, "src": "modul", "id": "P05-013"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Penggunaan 'di mana' yang membuat kalimat tidak efektif terdapat pada…", "opts": ["Rumah di mana ia tinggal sangat sederhana.", "Di mana ia tinggal sekarang?", "Ia tidak tahu di mana kuncinya.", "Di mana pun kau berada, kabari aku."], "ans": 0, "why": "'Di mana' sebagai penghubung (terjemahan 'where') diganti 'tempat' atau 'yang': 'Rumah tempat ia tinggal...'", "lvl": 2, "code": null, "src": "modul", "id": "P05-014"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kalimat yang tidak logis karena konjungsi ganda adalah…", "opts": ["Karena hujan deras, maka acara dibatalkan.", "Karena hujan deras, acara dibatalkan.", "Acara dibatalkan karena hujan deras.", "Hujan deras sehingga acara dibatalkan."], "ans": 0, "why": "'Karena' dan 'maka' sama-sama penanda sebab-akibat; cukup salah satu.", "lvl": 1, "code": null, "src": "modul", "id": "P05-015"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kalimat yang padu (tanpa sisipan yang tidak perlu) adalah…", "opts": ["Makalah ini membahas teknologi robotika.", "Makalah ini membahas tentang teknologi robotika.", "Makalah ini membahas mengenai teknologi robotika.", "Makalah ini membicarakan daripada teknologi robotika."], "ans": 0, "why": "Kata 'tentang/mengenai/daripada' tidak disisipkan antara verba transitif dan objeknya.", "lvl": 1, "code": null, "src": "modul", "id": "P05-016"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kalimat yang paralel adalah…", "opts": ["Pak Guru menolong anak itu dengan memapahnya ke pinggir jalan.", "Pak Guru menolong anak itu dengan dipapahnya ke pinggir jalan.", "Pak Guru ditolong anak itu dengan memapahnya ke pinggir jalan.", "Pak Guru menolong anak itu dengan papahan ke pinggir jalan."], "ans": 0, "why": "Bentuk verba harus sejajar: menolong ... memapah (sama-sama me-).", "lvl": 1, "code": null, "src": "modul", "id": "P05-017"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Pasangan konjungsi yang benar adalah…", "opts": ["baik ... maupun", "baik ... dan", "tidak hanya ... melainkan", "bukan ... tetapi juga"], "ans": 0, "why": "Pasangan baku: baik ... maupun; tidak hanya ... tetapi juga; bukan ... melainkan.", "lvl": 1, "code": null, "src": "modul", "id": "P05-018"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Urutan kata yang bertahap (klimaks) untuk ketegasan adalah…", "opts": ["seratus, seribu, sejuta, berjuta-juta", "seribu, sejuta, seratus, berjuta-juta", "sejuta, seribu, seratus, berjuta-juta", "berjuta-juta, seratus, seribu, sejuta"], "ans": 0, "why": "Ketegasan bisa dicapai dengan urutan yang makin meningkat.", "lvl": 2, "code": null, "src": "modul", "id": "P05-019"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Partikel penegasan dalam bahasa Indonesia adalah…", "opts": ["-lah, -pun, -kah", "-nya, -ku, -mu", "-an, -i, -kan", "di-, ke-, se-"], "ans": 0, "why": "Partikel -lah, -pun, -kah dipakai untuk penekanan.", "lvl": 1, "code": null, "src": "modul", "id": "P05-020"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Penerapan sistem informasi akademik adalah merupakan langkah yang sangat penting sekali bagi kampus.' Kata yang harus dihilangkan agar kalimat efektif adalah…", "opts": ["adalah/merupakan (salah satu) dan sangat/sekali (salah satu)", "penerapan dan bagi", "langkah dan kampus", "sistem dan akademik"], "ans": 0, "why": "'adalah merupakan' dan 'sangat ... sekali' sama-sama pleonasme; cukup pakai salah satu.", "lvl": 1, "code": null, "src": "uts", "id": "P05-021"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Para pengunjung-pengunjung dimohon agar supaya menjaga kebersihan.' Kalimat efektifnya adalah…", "opts": ["Para pengunjung dimohon menjaga kebersihan.", "Para pengunjung-pengunjung dimohon menjaga kebersihan.", "Pengunjung-pengunjung dimohon agar supaya menjaga kebersihan.", "Para pengunjung dimohon agar supaya menjaga kebersihan."], "ans": 0, "why": "'Para' sudah jamak sehingga kata tidak diulang; 'agar supaya' bersinonim.", "lvl": 1, "code": null, "src": "uts", "id": "P05-022"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang TIDAK efektif adalah…", "opts": ["Kami mengharapkan agar seluruh mahasiswa mengisi presensi.", "Kami berharap mahasiswa mengisi presensi.", "Seluruh mahasiswa diharapkan mengisi presensi.", "Kami mengharapkan seluruh mahasiswa mengisi presensi."], "ans": 0, "why": "'mengharapkan agar' pleonastis karena makna harapan sudah ada pada verba.", "lvl": 1, "code": null, "src": "uts", "id": "P05-023"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Di kota Malang menyelenggarakan festival kuliner.' Perbaikan agar kalimat efektif adalah…", "opts": ["menghilangkan kata 'Di' sehingga 'Kota Malang' menjadi subjek", "mengganti 'menyelenggarakan' dengan 'berfestival'", "mengganti 'kuliner' dengan 'makanan'", "menambahkan 'yang' setelah 'Malang'"], "ans": 0, "why": "Preposisi 'di' membuat kalimat tidak bersubjek. Tanpa 'di': 'Kota Malang menyelenggarakan festival kuliner.'", "lvl": 1, "code": null, "src": "uts", "id": "P05-024"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "'Agar tidak tersesat, wisatawan disarankan untuk jangan berjalan sendirian, melainkan berkelompok.' Pengganti yang tepat untuk bagian yang salah adalah…", "opts": ["tidak berjalan sendirian, tetapi", "bukan berjalan sendirian, melainkan", "jangan untuk berjalan sendirian, melainkan", "janganlah berjalan sendirian, melainkan"], "ans": 0, "why": "Pasangan 'tidak ... tetapi' tepat untuk verba; 'disarankan untuk jangan' tidak logis.", "lvl": 2, "code": null, "src": "uts", "id": "P05-025"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang efektif adalah…", "opts": ["Kamu harus berlatih rutin agar lolos seleksi.", "Saya mempersilahkan para hadirin sekalian duduk.", "Kami sejak dari pagi menunggumu di sini.", "Kita harus berolahraga agar supaya tubuh tetap selalu sehat."], "ans": 0, "why": "Opsi lain: 'mempersilahkan' tidak baku dan 'para hadirin sekalian' boros; 'sejak dari' dan 'agar supaya', 'tetap selalu' pleonasme.", "lvl": 1, "code": null, "src": "uts", "id": "P05-026"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Untuk dapat lulus tepat waktu, maka diperlukan perencanaan studi.' Perbaikan yang efektif adalah…", "opts": ["Untuk lulus tepat waktu, diperlukan perencanaan studi.", "Untuk lulus tepat waktu, maka diperlukan perencanaan studi.", "Untuk dapat lulus tepat waktu diperlukan perencanaan studi.", "Maka diperlukan perencanaan studi untuk lulus tepat waktu."], "ans": 0, "why": "Hilangkan 'dapat' (tidak perlu) dan 'maka' (konjungsi ganda dengan 'untuk').", "lvl": 1, "code": null, "src": "uts", "id": "P05-027"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kalimat yang paling efektif dan logis adalah…", "opts": ["Karena ketuanya berhalangan, rapat itu ditunda.", "Karena ketuanya berhalangan sehingga rapat itu ditunda.", "Rapat itu ditunda karena sebab ketuanya berhalangan.", "Karena berhalangan, maka rapat itu ditunda."], "ans": 0, "why": "Satu penanda sebab cukup; 'karena ... sehingga', 'karena sebab', 'karena ... maka' adalah konjungsi ganda.", "lvl": 2, "code": null, "src": "uts", "id": "P05-028"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "'Produk ini terbukti menjaga daya tahan tubuh. Selain itu mampu memperbaiki kualitas tidur, baik anak-anak dan orang dewasa.' Perbaikan kalimat kedua yang tepat adalah…", "opts": ["Selain itu, produk ini mampu memperbaiki kualitas tidur, baik anak-anak maupun orang dewasa.", "Selain itu, mampu memperbaiki kualitas tidur, baik anak-anak dan orang dewasa.", "Selain itu, mampu memperbaiki kualitas tidur, antara anak-anak maupun orang dewasa.", "Selain itu mampu memperbaiki kualitas tidur antara anak-anak dan orang dewasa."], "ans": 0, "why": "Koma setelah 'Selain itu', subjek dimunculkan, dan pasangan konjungsi yang benar 'baik ... maupun'.", "lvl": 2, "code": null, "src": "uts", "id": "P05-029"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Para siswa-siswi diharapkan untuk dapat mengumpulkan tugas tepat waktu.' Kalimat tersebut tidak efektif karena…", "opts": ["mengandung pleonasme", "tidak memiliki predikat", "bermakna ganda", "menggunakan kata tidak baku"], "ans": 0, "why": "'Para' + kata ulang, serta 'untuk dapat', adalah pemborosan (pleonasme).", "lvl": 1, "code": null, "src": "uts", "id": "P05-030"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang mengandung pemborosan kata adalah…", "opts": ["Ia naik ke atas panggung untuk menerima piagam.", "Ia naik panggung untuk menerima piagam.", "Pemenang menerima piagam di panggung.", "Setiap pemenang menerima piagam."], "ans": 0, "why": "'naik ke atas' pleonasme karena 'naik' sudah bermakna ke atas.", "lvl": 1, "code": null, "src": "uts", "id": "P05-031"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "'Meskipun sudah lama merantau, ia tetap mengingat desa di mana ia dibesarkan.' Bagian yang menyebabkan kalimat tidak efektif adalah…", "opts": ["di mana", "meskipun sudah", "ia tetap", "dibesarkan"], "ans": 0, "why": "'di mana' sebagai penghubung relatif tidak baku; ganti dengan 'tempat': desa tempat ia dibesarkan.", "lvl": 1, "code": null, "src": "uts", "id": "P05-032"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang paling efektif dan hemat adalah…", "opts": ["Untuk meningkatkan layanan, petugas harus bekerja cepat.", "Dalam rangka untuk meningkatkan layanan, petugas harus bekerja cepat.", "Dalam usaha untuk meningkatkan layanan, maka petugas harus bekerja cepat.", "Untuk dapat meningkatkan layanan, maka petugas harus bekerja cepat."], "ans": 0, "why": "Hindari 'dalam rangka untuk', 'dalam usaha untuk', dan 'maka' setelah 'untuk'.", "lvl": 1, "code": null, "src": "uts", "id": "P05-033"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang efektif adalah…", "opts": ["Pembatasan jam operasional merupakan upaya mengurangi kemacetan.", "Mereka saling memaafkan satu sama lain setelah berselisih.", "Laporan itu membahas tentang pengelolaan sampah kampus.", "Bagi peserta yang terlambat harap melapor ke panitia."], "ans": 0, "why": "Opsi lain: 'saling ... satu sama lain' boros, 'membahas tentang' tidak padu, 'Bagi peserta ...' kehilangan subjek.", "lvl": 1, "code": null, "src": "uts", "id": "P05-034"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Para peserta pelatihan workshop “Strategi Pemasaran Digital UMKM” diharapkan memasuki ruangan karena sesi pembukaan segera dimulai.' Perbaikan yang tepat adalah menghilangkan kata…", "opts": ["pelatihan (bersinonim dengan workshop)", "para dan peserta", "ruangan dan sesi", "segera dan dimulai"], "ans": 0, "why": "'pelatihan' dan 'workshop' bermakna sama sehingga salah satunya dihilangkan.", "lvl": 2, "code": null, "src": "uts", "id": "P05-035"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "Kalimat yang memiliki subjek dan predikat yang jelas merupakan ciri kalimat efektif dari segi…", "opts": ["kesepadanan", "kehematan", "keparalelan", "ketegasan"], "ans": 0, "why": "Kesepadanan = keseimbangan pikiran dan struktur, ditandai S dan P yang jelas.", "lvl": 1, "code": null, "src": "uts", "id": "P05-036"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Para pengurus-pengurus organisasi wajib melaporkan kegiatannya.' Perbaikan bagian yang salah adalah…", "opts": ["Para pengurus organisasi wajib melaporkan", "Para pengurus-pengurus organisasi wajib laporkan", "Pengurus-pengurus organisasi wajib laporkan", "Para pengurus organisasi wajib laporkan"], "ans": 0, "why": "Hilangkan pengulangan kata setelah 'para' dan pertahankan bentuk aktif 'melaporkan'.", "lvl": 1, "code": null, "src": "uts", "id": "P05-037"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang sesuai kaidah kalimat efektif adalah…", "opts": ["Para tamu undangan dimohon menunggu sebentar.", "Tamu undangan dimohon untuk dapat menunggu sebentar.", "Para tamu-tamu dimohon untuk duduk.", "Para tamu undangan harap untuk menunggu sebentar."], "ans": 0, "why": "Tanpa 'untuk dapat', tanpa pengulangan kata setelah 'para'.", "lvl": 1, "code": null, "src": "uts", "id": "P05-038"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Dalam buku pelajaran harus menyajikan contoh yang mendidik.' Perbaikan yang efektif adalah…", "opts": ["Buku pelajaran harus menyajikan contoh yang mendidik.", "Dalam buku pelajaran harus disajikan contoh yang mendidik dan menyajikan.", "Pada buku pelajaran harus menyajikan contoh yang mendidik.", "Di dalam buku pelajaran harus menyajikan contoh yang mendidik."], "ans": 0, "why": "Hilangkan preposisi di awal agar 'Buku pelajaran' menjadi subjek.", "lvl": 1, "code": null, "src": "uts", "id": "P05-039"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Tim kami memang tim yang super rajin. Semua tugas-tugas selesai sebelum tenggat.' Perbaikan kalimat kedua yang efektif adalah…", "opts": ["Semua tugas selesai sebelum tenggat.", "Semua tugas-tugas selesai sebelum tenggat waktunya.", "Tugas-tugas semua selesai sebelum tenggat.", "Semua tugas-tugas sudah selesai."], "ans": 0, "why": "'Semua' sudah bermakna jamak sehingga kata tidak perlu diulang.", "lvl": 1, "code": null, "src": "uts", "id": "P05-040"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang TIDAK efektif adalah…", "opts": ["Kedua tim itu saling bekerja sama satu sama lain.", "Panitia membagikan konsumsi kepada peserta.", "Ia datang sesuai jadwal.", "Petugas mulai menata kursi."], "ans": 0, "why": "'saling', 'bekerja sama', dan 'satu sama lain' tumpang tindih maknanya.", "lvl": 1, "code": null, "src": "uts", "id": "P05-041"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "'Kegiatan pramuka di sekolah tidak mampu melatih kemandirian juga menumbuhkan kerja sama.' Perbaikan agar logis adalah…", "opts": ["Kegiatan pramuka di sekolah tidak hanya melatih kemandirian, tetapi juga menumbuhkan kerja sama.", "Kegiatan pramuka di sekolah mampu melatih kemandirian tetapi tidak menumbuhkan kerja sama.", "Kegiatan pramuka di sekolah tidak melatih kemandirian melainkan hanya kerja sama.", "Kegiatan pramuka di sekolah hanya melatih kemandirian tidak kerja sama."], "ans": 0, "why": "Pasangan konjungsi 'tidak hanya ... tetapi juga' membuat kalimat logis dan paralel.", "lvl": 2, "code": null, "src": "uts", "id": "P05-042"}, {"p": "P05", "tag": "ciri", "type": "mcq", "q": "'Para pelaku usaha kecil yang sudah bertahun-tahun bergerak di bidang kerajinan.' Perbaikan kalimat tidak efektif tersebut adalah…", "opts": ["Para pelaku usaha kecil yang sudah bertahun-tahun bergerak di bidang kerajinan akan mendapat bantuan modal.", "Para pelaku usaha kecil sudah bertahun-tahun bergerak di bidang kerajinan lamanya.", "Para pelaku usaha kecil yang bergerak di bidang kerajinan.", "Yang sudah bertahun-tahun bergerak di bidang kerajinan para pelaku usaha kecil."], "ans": 0, "why": "Kalimat semula hanya subjek panjang tanpa predikat; perlu ditambah predikat ('akan mendapat').", "lvl": 2, "code": null, "src": "uts", "id": "P05-043"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "Kalimat yang tidak hemat adalah…", "opts": ["Ia masuk ke dalam kelas dengan tergesa-gesa.", "Ia bergegas masuk kelas.", "Ia segera masuk ke kelas.", "Ia langsung masuk kelas."], "ans": 0, "why": "'masuk ke dalam' pleonasme karena 'masuk' sudah bermakna ke dalam.", "lvl": 1, "code": null, "src": "uts", "id": "P05-044"}, {"p": "P05", "tag": "hemat", "type": "mcq", "q": "'Panitia telah menjalankan acara sesuai susunan yang tertera dalam undangan, namun ternyata bahwa peserta masih merasa bingung.' Kata yang sebaiknya dihilangkan adalah…", "opts": ["bahwa", "sesuai", "telah", "dalam"], "ans": 0, "why": "'ternyata bahwa' tidak tepat; 'bahwa' hanya mengawali klausa objek/pelengkap.", "lvl": 2, "code": null, "src": "uts", "id": "P05-045"}, {"p": "P05", "tag": "definisi", "type": "mcq", "q": "Kalimat yang efektif adalah…", "opts": ["Kalau tidak ada yang menjemput, saya akan pulang sendiri.", "Jangan pergi sendirian, nanti hilang.", "Tak usah dipikirkan nanti selesai sendiri.", "Dengan sendirinya aku mau membantumu."], "ans": 0, "why": "Kalimat lengkap S dan P-nya pada induk dan anak kalimat; opsi lain menghilangkan subjek atau tidak logis.", "lvl": 2, "code": null, "src": "uts", "id": "P05-046"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Struktur kalimat 'Andi bermain bola' adalah…", "opts": ["S-P-O", "S-P-K", "S-P-Pel", "P-S-O", "S-O-P"], "ans": 0, "why": "Andi (S), bermain (P), bola (O/Pel). Pada materi: S-P-O.", "lvl": 1, "code": null, "src": "modul", "id": "P06-001"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Perbedaan objek dan pelengkap adalah…", "opts": ["Objek dapat menjadi subjek dalam kalimat pasif, pelengkap tidak", "Pelengkap dapat dipasifkan, objek tidak", "Objek selalu berupa keterangan waktu", "Keduanya sama", "Pelengkap selalu di awal kalimat"], "ans": 0, "why": "Tabel perbedaan objek-pelengkap pada BAB 5.", "lvl": 1, "code": null, "src": "modul", "id": "P06-002"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Fungsi kalimat yang paling mudah dipindahkan letaknya adalah…", "opts": ["Keterangan", "Subjek", "Predikat", "Objek", "Pelengkap"], "ans": 0, "why": "Keterangan paling beragam dan mudah berpindah.", "lvl": 1, "code": null, "src": "modul", "id": "P06-003"}, {"p": "P06", "tag": "jenis", "type": "mcq", "q": "Kalimat 'Tolong tutup pintunya!' termasuk kalimat…", "opts": ["Imperatif", "Deklaratif", "Interogatif", "Eksklamatif", "Majemuk"], "ans": 0, "why": "Kalimat perintah/permintaan.", "lvl": 1, "code": null, "src": "modul", "id": "P06-004"}, {"p": "P06", "tag": "majemuk", "type": "mcq", "q": "Kalimat majemuk setara ditandai oleh konjungsi…", "opts": ["dan, atau, tetapi", "karena, ketika, jika", "agar, supaya", "meskipun, walaupun", "sehingga, apabila"], "ans": 0, "why": "KMS memakai konjungsi koordinatif.", "lvl": 1, "code": null, "src": "modul", "id": "P06-005"}, {"p": "P06", "tag": "majemuk", "type": "mcq", "q": "'Ia tidak bisa datang karena motornya rusak' termasuk kalimat…", "opts": ["Majemuk bertingkat", "Majemuk setara", "Tunggal", "Imperatif", "Majemuk campuran"], "ans": 0, "why": "'karena' menandai anak kalimat (hubungan sebab).", "lvl": 1, "code": null, "src": "modul", "id": "P06-006"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Unsur yang kehadirannya selalu wajib dalam kalimat adalah…", "opts": ["subjek dan predikat", "subjek dan objek", "predikat dan keterangan", "objek dan pelengkap"], "ans": 0, "why": "Kalimat minimal terdiri atas S dan P.", "lvl": 1, "code": null, "src": "modul", "id": "P06-007"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Unsur kalimat yang paling mudah dipindah-pindah letaknya adalah…", "opts": ["keterangan", "subjek", "predikat", "objek"], "ans": 0, "why": "Keterangan bisa di awal, tengah, atau akhir: 'Di kamar, dia memotong rambutnya.'", "lvl": 1, "code": null, "src": "modul", "id": "P06-008"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Perbedaan objek dan pelengkap yang benar adalah…", "opts": ["Objek dapat menjadi subjek kalimat pasif, pelengkap tidak", "Pelengkap dapat diganti -nya, objek tidak", "Objek selalu berupa kata sifat", "Pelengkap hanya muncul pada kalimat pasif"], "ans": 0, "why": "Objek bisa dipasifkan (Roti dimakan Ayah); pelengkap tidak (*Matematika diajar adik).", "lvl": 1, "code": null, "src": "modul", "id": "P06-009"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Pada kalimat 'Ia menjadi tentara', kata 'tentara' berfungsi sebagai…", "opts": ["pelengkap", "objek", "keterangan", "subjek"], "ans": 0, "why": "'Menjadi' tidak menuntut objek; 'tentara' melengkapi predikat sehingga berfungsi sebagai pelengkap.", "lvl": 2, "code": null, "src": "modul", "id": "P06-010"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Pada kalimat 'Melukis hobiku', subjeknya berupa…", "opts": ["verba (kata kerja)", "nomina", "klausa", "adjektiva"], "ans": 0, "why": "Subjek bisa berupa verba; kalimat seperti ini disebut kalimat substantif.", "lvl": 2, "code": null, "src": "modul", "id": "P06-011"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Pola kalimat 'Bella berjualan suvenir' adalah…", "opts": ["S-P-Pel", "S-P-O", "S-P-K", "S-P-O-Pel"], "ans": 0, "why": "Berjualan adalah verba intransitif (ber-), jadi 'suvenir' adalah pelengkap.", "lvl": 1, "code": null, "src": "modul", "id": "P06-012"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Pola kalimat 'Dian mengambilkan adiknya air minum' adalah…", "opts": ["S-P-O-Pel", "S-P-O-K", "S-P-Pel", "S-P-O"], "ans": 0, "why": "'adiknya' = objek (bisa dipasifkan), 'air minum' = pelengkap.", "lvl": 2, "code": null, "src": "modul", "id": "P06-013"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Pola kalimat 'Pak Raden memasukkan uang ke bank' adalah…", "opts": ["S-P-O-K", "S-P-O-Pel", "S-P-K", "S-P-Pel-K"], "ans": 0, "why": "'ke bank' adalah keterangan tempat.", "lvl": 1, "code": null, "src": "modul", "id": "P06-014"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Kalimat berpola S-P-K adalah…", "opts": ["Kami tinggal di Jakarta.", "Ayahnya membeli mobil baru.", "Mereka bermain bola.", "Saya mahasiswa."], "ans": 0, "why": "S (Kami) – P (tinggal) – K (di Jakarta).", "lvl": 1, "code": null, "src": "modul", "id": "P06-015"}, {"p": "P06", "tag": "jenis", "type": "mcq", "q": "Kalimat 'Amboi, indah sekali pemandangan di kota ini!' termasuk kalimat…", "opts": ["eksklamatif (seru)", "imperatif", "interogatif", "deklaratif"], "ans": 0, "why": "Kalimat seru/eksklamatif ditandai interjeksi dan tanda seru.", "lvl": 1, "code": null, "src": "modul", "id": "P06-016"}, {"p": "P06", "tag": "majemuk", "type": "mcq", "q": "Kalimat 'Soal-soal itu tidak ada yang sulit, bahkan tergolong mudah' adalah kalimat majemuk setara hubungan…", "opts": ["penegasan/penguatan", "penjumlahan", "pertentangan", "pemilihan"], "ans": 0, "why": "Konjungsi 'bahkan' menandai hubungan penegasan.", "lvl": 2, "code": null, "src": "modul", "id": "P06-017"}, {"p": "P06", "tag": "majemuk", "type": "mcq", "q": "'Ia tidak mengetahui bahwa kami telah lulus ujian' adalah kalimat majemuk bertingkat dengan anak kalimat pengganti…", "opts": ["objek", "subjek", "predikat", "keterangan"], "ans": 0, "why": "Klausa 'bahwa kami telah lulus ujian' menduduki fungsi objek dari 'mengetahui'.", "lvl": 2, "code": null, "src": "modul", "id": "P06-018"}, {"p": "P06", "tag": "majemuk", "type": "mcq", "q": "'Saya menulis surat dan adik menonton televisi ketika ayah pulang' termasuk kalimat majemuk…", "opts": ["campuran", "setara", "bertingkat", "tunggal"], "ans": 0, "why": "Ada dua induk kalimat setara (dan) ditambah anak kalimat (ketika...), jadi campuran.", "lvl": 2, "code": null, "src": "modul", "id": "P06-019"}, {"p": "P06", "tag": "jenis", "type": "mcq", "q": "Kalimat 'Adik kehujanan di jalan' termasuk kalimat pasif dengan predikat…", "opts": ["konfiks ke-an", "awalan di-", "awalan ter-", "awalan me-"], "ans": 0, "why": "Pasif bisa berbentuk di-, ter-, atau ke-an. 'Kehujanan' = ke-an.", "lvl": 1, "code": null, "src": "modul", "id": "P06-020"}, {"p": "P06", "tag": "jenis", "type": "mcq", "q": "Kalimat aktif intransitif adalah…", "opts": ["Paman berjualan bayam.", "Adik memakan roti.", "Ayah membeli mobil.", "Rani mengirimi ibunya surat."], "ans": 0, "why": "Berjualan tidak menuntut objek (bayam = pelengkap). Opsi lain transitif.", "lvl": 1, "code": null, "src": "modul", "id": "P06-021"}, {"p": "P06", "tag": "jenis", "type": "mcq", "q": "Kalimat 'Ayahku pengacara' termasuk kalimat…", "opts": ["nominal", "verbal", "adjektival", "numeral"], "ans": 0, "why": "Predikatnya kata benda (pengacara), jadi kalimat nominal.", "lvl": 1, "code": null, "src": "modul", "id": "P06-022"}, {"p": "P06", "tag": "jenis", "type": "mcq", "q": "Kalimat 'Pergi!' termasuk kalimat…", "opts": ["tak lengkap (minor)", "lengkap (mayor)", "majemuk", "inversi"], "ans": 0, "why": "Kalimat minor hanya mengandung satu unsur pusat (S atau P saja).", "lvl": 1, "code": null, "src": "modul", "id": "P06-023"}, {"p": "P06", "tag": "majemuk", "type": "mcq", "q": "Penggunaan konjungsi dalam kalimat majemuk setara yang tepat adalah…", "opts": ["Mereka datang ke panti, tetapi tidak membawa bantuan apa pun.", "Mereka datang ke panti, melainkan tidak membawa bantuan.", "Mereka datang ke panti, namun tidak membawa bantuan.", "Mereka datang ke panti baik dulu dan sekarang."], "ans": 0, "why": "Pertentangan antarklausa memakai 'tetapi' didahului koma. 'Melainkan' berpasangan dengan 'bukan'; 'namun' adalah penghubung antarkalimat; 'baik' berpasangan dengan 'maupun'.", "lvl": 2, "code": null, "src": "uts", "id": "P06-024"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Pertumbuhan ekonomi daerah sangat bergantung pada sektor pariwisata dan pertanian.' Pola kalimat tersebut adalah…", "opts": ["S-P-K", "S-P-O", "S-P-O-K", "S-P-Pel-K"], "ans": 0, "why": "S (Pertumbuhan ekonomi daerah) – P (sangat bergantung) – K (pada sektor pariwisata dan pertanian). Frasa berpreposisi adalah keterangan.", "lvl": 2, "code": null, "src": "uts", "id": "P06-025"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Meskipun sudah sepuluh tahun bekerja di kota, ia tetap merindukan kampung halamannya.' Struktur kalimat tersebut adalah…", "opts": ["K-S-P-O", "S-P-O-K", "K-S-P-Pel", "S-P-K"], "ans": 0, "why": "Anak kalimat 'Meskipun ...' menjadi keterangan di depan, lalu S (ia), P (tetap merindukan), O (kampung halamannya).", "lvl": 2, "code": null, "src": "uts", "id": "P06-026"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Tadi pagi kurir mengantarkan paket yang dipesan Ibu.' Kalimat yang berpola sama adalah…", "opts": ["Dengan semangat tinggi, para relawan membersihkan pantai yang tercemar.", "Para relawan membersihkan pantai yang tercemar.", "Pantai itu tercemar sejak minggu lalu.", "Para relawan bekerja dengan semangat tinggi."], "ans": 0, "why": "Pola K-S-P-O: keterangan di depan, lalu subjek, predikat, objek.", "lvl": 2, "code": null, "src": "uts", "id": "P06-027"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Sejak awal reformasi, Indonesia menerapkan sistem otonomi daerah yang memberi kewenangan luas kepada pemerintah daerah.' Unsur objek kalimat tersebut adalah…", "opts": ["sistem otonomi daerah yang memberi kewenangan luas kepada pemerintah daerah", "sistem otonomi daerah", "sejak awal reformasi", "Indonesia menerapkan sistem otonomi daerah"], "ans": 0, "why": "Objek mencakup seluruh frasa nomina beserta perluasannya ('yang memberi kewenangan...').", "lvl": 3, "code": null, "src": "uts", "id": "P06-028"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Semua mahasiswa yang mengikuti magang wajib mengikuti pembekalan selama tiga hari.' Struktur kalimat majemuk bertingkat yang benar adalah…", "opts": ["S (s-p-o) - P - O - K", "S - P - O - K", "S - P - K", "S - P (p2) - O - K"], "ans": 0, "why": "Subjek diperluas oleh klausa 'yang mengikuti magang' (s-p-o), lalu P (wajib mengikuti), O (pembekalan), K (selama tiga hari).", "lvl": 3, "code": null, "src": "uts", "id": "P06-029"}, {"p": "P06", "tag": "majemuk", "type": "mcq", "q": "Kalimat yang strukturnya benar adalah…", "opts": ["Walaupun hujan turun deras, para pendaki tetap melanjutkan perjalanan.", "Walaupun hujan turun deras, tetapi para pendaki tetap melanjutkan perjalanan.", "Walaupun hujan turun deras, namun para pendaki tetap melanjutkan perjalanan.", "Walaupun hujan turun deras, akan tetapi para pendaki tetap melanjutkan perjalanan."], "ans": 0, "why": "Kalimat majemuk bertingkat hanya memakai satu konjungsi; 'walaupun' tidak dipasangkan dengan 'tetapi/namun'.", "lvl": 1, "code": null, "src": "uts", "id": "P06-030"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Bagian kalimat yang memberi penjelasan tentang tempat, waktu, cara, atau alasan disebut…", "opts": ["keterangan", "objek", "pelengkap", "predikat"], "ans": 0, "why": "Keterangan menjelaskan unsur lain dalam kalimat dan paling mudah dipindah.", "lvl": 1, "code": null, "src": "uts", "id": "P06-031"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Koperasi mahasiswa dapat membantu kebutuhan anggotanya dengan harga terjangkau.' Struktur kalimat tersebut adalah…", "opts": ["S-P-O-K", "S-P-K", "S-P-Pel-K", "S-P-O"], "ans": 0, "why": "S (Koperasi mahasiswa) – P (dapat membantu) – O (kebutuhan anggotanya) – K (dengan harga terjangkau).", "lvl": 2, "code": null, "src": "uts", "id": "P06-032"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Infaq sangat penting bagi kegiatan sosial masjid.' Struktur kalimat tersebut adalah…", "opts": ["S-P-K", "S-P-O", "S-P-Pel", "S-P-O-K"], "ans": 0, "why": "S (Infaq) – P (sangat penting) – K (bagi kegiatan sosial masjid). Predikat adjektiva tidak menuntut objek.", "lvl": 2, "code": null, "src": "uts", "id": "P06-033"}, {"p": "P06", "tag": "jenis", "type": "mcq", "q": "Bentuk pasif dari 'Kami akan menyerahkan semua berkas ini kepada panitia' adalah…", "opts": ["Semua berkas ini akan kami serahkan kepada panitia.", "Semua berkas ini akan diserahkan oleh kami kepada panitia.", "Kami akan diserahkan kepada panitia oleh berkas ini.", "Kami akan serahkan semua berkas ini kepada panitia."], "ans": 0, "why": "Pelaku persona pertama/kedua dalam pasif diletakkan langsung sebelum verba tanpa 'oleh': akan kami serahkan.", "lvl": 3, "code": null, "src": "uts", "id": "P06-034"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Sebelum ujian dimulai, setiap mahasiswa harus menunjukkan kartu ujian kepada pengawas.' Pola kalimat tersebut adalah…", "opts": ["K-S-P-O-K", "K-S-P-O", "S-P-O-K", "S-P-Pel-O-K"], "ans": 0, "why": "K (Sebelum ujian dimulai) – S (setiap mahasiswa) – P (harus menunjukkan) – O (kartu ujian) – K (kepada pengawas).", "lvl": 2, "code": null, "src": "uts", "id": "P06-035"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Kalimat yang berpola S-P-O adalah…", "opts": ["Rina belum menyelesaikan laporan praktikumnya.", "Sudah dua hari ini, Rina tidak masuk kuliah.", "Bahasa Inggris harus dipelajari sejak dini.", "Bahasa Indonesia merupakan bahasa yang kaya imbuhan."], "ans": 0, "why": "S (Rina) – P (belum menyelesaikan) – O (laporan praktikumnya).", "lvl": 1, "code": null, "src": "uts", "id": "P06-036"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "'Isu keamanan data pengguna aplikasi daring menjadi perhatian utama pemerintah tahun ini.' Unsur subjek kalimat tersebut adalah…", "opts": ["isu keamanan data pengguna aplikasi daring", "isu keamanan data", "data pengguna aplikasi daring", "perhatian utama pemerintah"], "ans": 0, "why": "Subjek mencakup seluruh frasa nomina sebelum predikat 'menjadi'.", "lvl": 2, "code": null, "src": "uts", "id": "P06-037"}, {"p": "P06", "tag": "fungsi", "type": "mcq", "q": "Kalimat efektif berstruktur S-P-O-K adalah…", "opts": ["Para mahasiswa mengerjakan kuis di laboratorium.", "Mengerjakan para mahasiswa kuis di laboratorium.", "Di laboratorium sedang mengerjakan kuis para mahasiswa.", "Para mahasiswa di laboratorium mengerjakan."], "ans": 0, "why": "S (Para mahasiswa) – P (mengerjakan) – O (kuis) – K (di laboratorium).", "lvl": 1, "code": null, "src": "uts", "id": "P06-038"}, {"p": "P07", "tag": "syarat", "type": "mcq", "q": "Tiga syarat paragraf yang baik adalah…", "opts": ["Kepaduan, kesatuan, kelengkapan", "Kehematan, keparalelan, ketegasan", "Pendahuluan, isi, penutup", "Topik, tema, judul", "Subjek, predikat, objek"], "ans": 0, "why": "Syarat paragraf menurut BAB 9.", "lvl": 1, "code": null, "src": "modul", "id": "P07-001"}, {"p": "P07", "tag": "syarat", "type": "mcq", "q": "Penggunaan kata ganti dan kata transisi dalam paragraf berfungsi menciptakan…", "opts": ["Kepaduan (koherensi)", "Kesatuan", "Kelengkapan", "Keparalelan", "Kehematan"], "ans": 0, "why": "Alat kepaduan: repetisi, kata ganti, transisi, urutan isi.", "lvl": 1, "code": null, "src": "modul", "id": "P07-002"}, {"p": "P07", "tag": "letak", "type": "mcq", "q": "Paragraf yang kalimat utamanya di awal disebut…", "opts": ["Deduktif", "Induktif", "Campuran", "Deskriptif", "Naratif"], "ans": 0, "why": "Deduktif = umum di awal; induktif = di akhir.", "lvl": 1, "code": null, "src": "modul", "id": "P07-003"}, {"p": "P07", "tag": "isi", "type": "mcq", "q": "Paragraf yang berisi ajakan agar pembaca melakukan sesuatu disebut…", "opts": ["Persuasi", "Eksposisi", "Deskripsi", "Narasi", "Argumentasi"], "ans": 0, "why": "Persuasi bertujuan mengajak.", "lvl": 1, "code": null, "src": "modul", "id": "P07-004"}, {"p": "P07", "tag": "isi", "type": "mcq", "q": "Paragraf yang menjelaskan tahapan proses suatu kegiatan disebut…", "opts": ["Eksposisi", "Narasi", "Deskripsi", "Persuasi", "Argumentasi"], "ans": 0, "why": "Eksposisi menjelaskan/memaparkan.", "lvl": 1, "code": null, "src": "modul", "id": "P07-005"}, {"p": "P07", "tag": "syarat", "type": "mcq", "q": "Bagian lahiriah paragraf menurut Tarigan adalah…", "opts": ["kalimat topik, kalimat penjelas, kalimat penegas, penghubung antarkalimat", "judul, isi, penutup", "kata, frasa, klausa", "pendahuluan, isi, simpulan, saran"], "ans": 0, "why": "Paragraf terdiri atas kalimat topik/utama, penjelas, penegas, dan penghubung antarkalimat.", "lvl": 2, "code": null, "src": "modul", "id": "P07-006"}, {"p": "P07", "tag": "syarat", "type": "mcq", "q": "Syarat paragraf 'semua kalimat mendukung satu pikiran utama' disebut…", "opts": ["kesatuan", "kepaduan", "kelengkapan", "keparalelan"], "ans": 0, "why": "Kesatuan = satu pikiran utama menjiwai seluruh paragraf.", "lvl": 1, "code": null, "src": "modul", "id": "P07-007"}, {"p": "P07", "tag": "syarat", "type": "mcq", "q": "Paragraf yang kalimat penjelasnya cukup menunjang kalimat topik memenuhi syarat…", "opts": ["kelengkapan", "kesatuan", "kepaduan", "ketegasan"], "ans": 0, "why": "Kelengkapan = ketuntasan pembicaraan dengan penjelas yang cukup.", "lvl": 1, "code": null, "src": "modul", "id": "P07-008"}, {"p": "P07", "tag": "syarat", "type": "mcq", "q": "Paragraf yang hanya terdiri atas satu kalimat disebut paragraf…", "opts": ["sederhana", "sempurna", "deskriptif", "ineratif"], "ans": 0, "why": "Ermanto & Emidar: paragraf beberapa kalimat = sempurna; satu kalimat = sederhana.", "lvl": 3, "code": null, "src": "modul", "id": "P07-009"}, {"p": "P07", "tag": "letak", "type": "mcq", "q": "Paragraf yang kalimat utamanya di awal dan diulang/ditegaskan di akhir disebut paragraf…", "opts": ["campuran/variatif", "deduktif", "induktif", "ineratif"], "ans": 0, "why": "Campuran: kalimat utama di awal dan di akhir.", "lvl": 1, "code": null, "src": "modul", "id": "P07-010"}, {"p": "P07", "tag": "letak", "type": "mcq", "q": "Paragraf yang seluruh kalimatnya penting sehingga tidak memiliki kalimat utama disebut paragraf…", "opts": ["deskriptif", "deduktif", "induktif", "campuran"], "ans": 0, "why": "Paragraf deskriptif (berdasarkan letak) tidak memiliki kalimat utama.", "lvl": 2, "code": null, "src": "modul", "id": "P07-011"}, {"p": "P07", "tag": "letak", "type": "mcq", "q": "Kata yang biasa mengawali kalimat simpulan dalam paragraf induktif adalah…", "opts": ["jadi, dengan demikian, oleh sebab itu", "pertama, kedua, ketiga", "misalnya, contohnya", "selain itu, di samping itu"], "ans": 0, "why": "Kalimat utama paragraf induktif berada di akhir dan sering diawali kata penanda simpulan.", "lvl": 1, "code": null, "src": "modul", "id": "P07-012"}, {"p": "P07", "tag": "isi", "type": "mcq", "q": "Paragraf yang memuat tokoh, peristiwa, dan latar disebut paragraf…", "opts": ["narasi", "deskripsi", "eksposisi", "argumentasi"], "ans": 0, "why": "Narasi = cerita dengan tokoh, peristiwa, latar.", "lvl": 1, "code": null, "src": "modul", "id": "P07-013"}, {"p": "P07", "tag": "isi", "type": "mcq", "q": "Tulisan yang menyatakan pendapat bahwa integrasi sistem informasi lebih baik, lengkap dengan data jam kerja dan alasannya, adalah contoh paragraf…", "opts": ["argumentasi", "narasi", "deskripsi", "persuasi"], "ans": 0, "why": "Paragraf argumentasi berisi pendapat yang didukung alasan dan data.", "lvl": 2, "code": null, "src": "modul", "id": "P07-014"}, {"p": "P07", "tag": "kembang", "type": "mcq", "q": "Paragraf yang menjelaskan sesuatu yang belum dikenal dengan membandingkannya pada sesuatu yang sudah dikenal dikembangkan dengan teknik…", "opts": ["analogi", "perbandingan", "generalisasi", "klasifikasi"], "ans": 0, "why": "Analogi, misalnya 'merawat tanaman sama halnya dengan merawat anak'.", "lvl": 1, "code": null, "src": "modul", "id": "P07-015"}, {"p": "P07", "tag": "kembang", "type": "mcq", "q": "'Dini hari Bu Ratna bangun. Kemudian ia ke pasar. Sesampainya di pasar ia membuka lapak.' Paragraf ini dikembangkan dengan teknik…", "opts": ["kronologi", "sebab-akibat", "contoh", "definisi"], "ans": 0, "why": "Kronologi berdasarkan urutan waktu kejadian.", "lvl": 1, "code": null, "src": "modul", "id": "P07-016"}, {"p": "P07", "tag": "kembang", "type": "mcq", "q": "Paragraf yang dimulai dengan peristiwa akibat (banjir), lalu diuraikan penyebabnya, dikembangkan dengan teknik…", "opts": ["akibat-sebab", "sebab-akibat", "sebab-akibat 1-akibat 2", "generalisasi"], "ans": 0, "why": "Akibat disebut lebih dulu, baru sebab-sebabnya.", "lvl": 1, "code": null, "src": "modul", "id": "P07-017"}, {"p": "P07", "tag": "kembang", "type": "mcq", "q": "Paragraf yang mengelompokkan ilmu bahasa menjadi sintaktik, fonologi, dan semantik dikembangkan dengan teknik…", "opts": ["klasifikasi", "perbandingan", "definisi", "contoh"], "ans": 0, "why": "Klasifikasi = pengelompokan objek/bidang.", "lvl": 1, "code": null, "src": "modul", "id": "P07-018"}, {"p": "P09", "tag": "argumen", "type": "mcq", "q": "Paragraf argumentasi bertujuan…", "opts": ["Meyakinkan pembaca dengan alasan dan bukti", "Menceritakan kisah", "Menggambarkan suasana", "Mengajak membeli produk", "Menghibur"], "ans": 0, "why": "Argumentasi = pendapat + bukti.", "lvl": 1, "code": null, "src": "modul", "id": "P09-001"}, {"p": "P09", "tag": "penalaran", "type": "mcq", "q": "Penalaran yang menarik simpulan umum dari beberapa fakta khusus disebut…", "opts": ["Induktif", "Deduktif", "Silogisme", "Entimem", "Analogi terbalik"], "ans": 0, "why": "Induktif: khusus → umum.", "lvl": 1, "code": null, "src": "modul", "id": "P09-002"}, {"p": "P10", "tag": "ciri", "type": "mcq", "q": "Topik dalam karya ilmiah adalah…", "opts": ["Pokok pembicaraan dalam tulisan", "Amanat utama penulis", "Kesimpulan penelitian", "Daftar pustaka", "Judul bab"], "ans": 0, "why": "Topik = pokok pembicaraan; tema = amanat utama (Keraf).", "lvl": 1, "code": null, "src": "modul", "id": "P10-001"}, {"p": "P10", "tag": "ciri", "type": "mcq", "q": "Langkah setelah menentukan topik dalam penulisan karya ilmiah adalah…", "opts": ["Merumuskan masalah, tujuan, dan ruang lingkup", "Menulis daftar pustaka", "Menyusun simpulan", "Mencetak naskah", "Membuat abstrak"], "ans": 0, "why": "Urutan langkah penulisan karya ilmiah.", "lvl": 1, "code": null, "src": "modul", "id": "P10-002"}, {"p": "P10", "tag": "penelitian", "type": "mcq", "q": "Penelitian yang hasilnya diperoleh melalui prosedur statistik disebut…", "opts": ["Kuantitatif", "Kualitatif", "Deskriptif naratif", "Studi literatur saja", "Etnografi"], "ans": 0, "why": "Kuantitatif berakar positivisme dan memakai angka.", "lvl": 1, "code": null, "src": "modul", "id": "P10-003"}, {"p": "P10", "tag": "ciri", "type": "mcq", "q": "Simpulan dalam karya ilmiah merupakan…", "opts": ["Jawaban atas rumusan masalah", "Ringkasan teori", "Daftar istilah", "Latar belakang", "Ucapan terima kasih"], "ans": 0, "why": "BAB 7: simpulan menjawab rumusan masalah.", "lvl": 1, "code": null, "src": "modul", "id": "P10-004"}, {"p": "P10", "tag": "penelitian", "type": "mcq", "q": "Penelitian yang temuannya tidak diperoleh melalui prosedur statistik disebut penelitian…", "opts": ["kualitatif", "kuantitatif", "eksperimen", "survei angka"], "ans": 0, "why": "Strauss & Corbin: kualitatif tidak memakai statistik; kuantitatif menganalisis angka secara statistik.", "lvl": 1, "code": null, "src": "modul", "id": "P10-005"}, {"p": "P10", "tag": "penelitian", "type": "mcq", "q": "Penelitian yang menguji teori dengan meneliti hubungan antarvariabel melalui data angka disebut…", "opts": ["kuantitatif", "kualitatif", "naratif", "etnografi"], "ans": 0, "why": "Kuantitatif: variabel diukur dengan instrumen, data dianalisis statistik.", "lvl": 1, "code": null, "src": "modul", "id": "P10-006"}, {"p": "P10", "tag": "penelitian", "type": "mcq", "q": "Menurut Keraf, 'pokok pembicaraan dalam tulisan ilmiah' adalah pengertian dari…", "opts": ["topik", "tema", "judul", "amanat"], "ans": 0, "why": "Topik = pokok pembicaraan; tema = amanat utama yang disampaikan penulis.", "lvl": 2, "code": null, "src": "modul", "id": "P10-007"}, {"p": "P10", "tag": "sistematika", "type": "mcq", "q": "Bagian makalah yang menjelaskan alasan pemilihan tema adalah…", "opts": ["latar belakang", "rumusan masalah", "tujuan", "simpulan"], "ans": 0, "why": "Latar belakang berisi alasan pemilihan tema/masalah.", "lvl": 1, "code": null, "src": "modul", "id": "P10-008"}, {"p": "P10", "tag": "sistematika", "type": "mcq", "q": "Rumusan masalah biasanya ditulis dalam bentuk…", "opts": ["kalimat tanya (bagaimana, apa, mengapa)", "kalimat perintah", "kalimat seru", "kalimat berita tanpa tanda tanya"], "ans": 0, "why": "Rumusan masalah memakai kalimat tanya.", "lvl": 1, "code": null, "src": "modul", "id": "P10-009"}, {"p": "P10", "tag": "sistematika", "type": "mcq", "q": "Jumlah kalimat simpulan pada bab penutup sebaiknya…", "opts": ["sesuai dengan jumlah rumusan masalah", "selalu satu kalimat", "lebih banyak dari rumusan masalah", "sama dengan jumlah bab"], "ans": 0, "why": "Simpulan menjawab setiap rumusan masalah.", "lvl": 1, "code": null, "src": "modul", "id": "P10-010"}, {"p": "P10", "tag": "sistematika", "type": "mcq", "q": "Dalam skripsi, bagian yang berisi rujukan teori sebagai dasar pemikiran terletak pada…", "opts": ["BAB II Tinjauan Pustaka/Dasar Teori", "BAB I Pendahuluan", "BAB III Metode Penelitian", "BAB V Penutup"], "ans": 0, "why": "BAB II memuat dasar teori dan dicantumkan sumbernya.", "lvl": 1, "code": null, "src": "modul", "id": "P10-011"}, {"p": "P10", "tag": "sistematika", "type": "mcq", "q": "Bagian pendahuluan skripsi yang TIDAK wajib ada di semua lembaga adalah…", "opts": ["definisi operasional", "latar belakang", "rumusan masalah", "tujuan"], "ans": 0, "why": "Definisi operasional bukan komponen wajib.", "lvl": 2, "code": null, "src": "modul", "id": "P10-012"}, {"p": "P10", "tag": "sistematika", "type": "mcq", "q": "Urutan langkah menulis karya ilmiah yang benar adalah…", "opts": ["menentukan topik – merumuskan masalah & tujuan – mengumpulkan bahan – menyusun kerangka", "mengumpulkan bahan – menentukan topik – menyusun kerangka – merumuskan masalah", "menyusun kerangka – menentukan topik – mengumpulkan bahan – merumuskan masalah", "merumuskan masalah – menyusun kerangka – menentukan topik – mengumpulkan bahan"], "ans": 0, "why": "Langkah: topik → masalah, tujuan, ruang lingkup → kumpulkan bahan → kerangka.", "lvl": 2, "code": null, "src": "modul", "id": "P10-013"}, {"p": "P10", "tag": "sistematika", "type": "mcq", "q": "Penulisan judul karya ilmiah yang benar adalah…", "opts": ["Analisis Pengaruh Promosi terhadap Penjualan pada PT Martina Berto", "Analisa Pengaruh Promosi Terhadap Penjualan Pada PT. Martina Berto", "Analisis pengaruh promosi terhadap penjualan pada PT Martina Berto.", "ANALISA PENGARUH PROMOSI TERHADAP PENJUALAN PADA PT. MARTINA BERTO."], "ans": 0, "why": "Judul: kata baku (analisis), kata tugas (terhadap, pada) huruf kecil, PT tanpa titik, tanpa titik di akhir.", "lvl": 1, "code": null, "src": "modul", "id": "P10-014"}, {"p": "P10", "tag": "ciri", "type": "mcq", "q": "Penulisan judul laporan kegiatan yang paling tepat adalah…", "opts": ["Pelatihan Penulisan Karya Ilmiah bagi Mahasiswa Baru", "PELATIHAN PENULISAN KARYA ILMIAH BAGI MAHASISWA BARU.", "Pelatihan Penulisan Karya Ilmiah Bagi Mahasiswa Baru.", "Laporan Kunjungan ke-Perpustakaan Nasional"], "ans": 0, "why": "Judul tanpa titik di akhir, kata tugas (bagi) huruf kecil. 'ke' kata depan ditulis terpisah tanpa tanda hubung.", "lvl": 2, "code": null, "src": "uts", "id": "P10-015"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Penulisan '…bahasa yang banyak dipelajari penutur asing (Siroj, 2015).' adalah contoh…", "opts": ["Bodynote (catatan perut)", "Footnote", "Daftar pustaka", "Endnote", "Abstrak"], "ans": 0, "why": "Kutipan di dalam teks.", "lvl": 1, "code": null, "src": "modul", "id": "P11-001"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Aplikasi pengelola referensi yang disebut dalam materi adalah…", "opts": ["Mendeley, Zotero, EndNote", "Photoshop, CorelDraw", "Excel, PowerPoint", "Chrome, Firefox", "WhatsApp, Telegram"], "ans": 0, "why": "Pengelola referensi online.", "lvl": 1, "code": null, "src": "modul", "id": "P11-002"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Daftar pustaka disusun berdasarkan…", "opts": ["Urutan alfabet nama belakang penulis", "Tahun terbit terbaru", "Urutan kemunculan di teks", "Tebal buku", "Nama penerbit"], "ans": 0, "why": "Daftar pustaka alfabetis.", "lvl": 1, "code": null, "src": "modul", "id": "P11-003"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Penulisan daftar pustaka format APA yang benar adalah…", "opts": ["Siroj, M. B. (2015). Judul artikel. Nama Jurnal, 4(1), 74–84.", "M. B. Siroj. 2015, Judul artikel, Nama Jurnal", "(2015) Siroj M B. Judul artikel.", "Judul artikel. Siroj, 2015. Nama Jurnal.", "Siroj (Judul artikel) 2015 Nama Jurnal 74-84"], "ans": 0, "why": "Format APA: Nama belakang, inisial. (tahun). Judul. Jurnal, vol(no), halaman.", "lvl": 2, "code": null, "src": "modul", "id": "P11-004"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Unsur yang dicantumkan dalam bodynote adalah…", "opts": ["nama belakang penulis, tahun, halaman", "nama lengkap, judul, penerbit", "judul, kota, tahun", "nama lengkap, kota, penerbit, tahun"], "ans": 0, "why": "Bodynote: nama penulis (cukup nama belakang), tahun terbit, dan halaman.", "lvl": 1, "code": null, "src": "modul", "id": "P11-005"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Kutipan langsung yang kurang dari empat baris ditulis…", "opts": ["menyatu dengan teks dan diapit tanda petik", "terpisah dari teks dan menjorok", "tanpa tanda petik dan dicetak tebal", "di catatan kaki"], "ans": 0, "why": "Kutipan pendek: < 4 baris, terintegrasi dalam teks, spasi sama, diapit tanda petik.", "lvl": 1, "code": null, "src": "modul", "id": "P11-006"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Ciri kutipan langsung panjang adalah…", "opts": ["empat baris atau lebih, dipisah dari teks, menjorok 5-7 ketukan", "kurang dari empat baris dan wajib diapit tanda petik", "ditulis dengan bahasa sendiri", "selalu diletakkan di catatan kaki"], "ans": 0, "why": "Kutipan panjang dipisahkan dari teks dan menjorok; tanda petik boleh ada boleh tidak.", "lvl": 1, "code": null, "src": "modul", "id": "P11-007"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Kutipan yang mengambil ide pokok lalu ditulis dengan bahasa sendiri disebut…", "opts": ["kutipan tidak langsung (parafrasa)", "kutipan langsung pendek", "kutipan langsung panjang", "catatan kaki"], "ans": 0, "why": "Kutipan tidak langsung tidak memakai tanda petik.", "lvl": 1, "code": null, "src": "modul", "id": "P11-008"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Tanda (sic!) dalam kutipan berarti…", "opts": ["ada kesalahan di naskah asli yang dibiarkan apa adanya", "ada bagian kutipan yang dihilangkan", "kutipan berasal dari sumber kedua", "kutipan diterjemahkan"], "ans": 0, "why": "(sic!) menandai kesalahan dari naskah asal yang tidak diubah. Bagian yang dihilangkan ditandai (...).", "lvl": 2, "code": null, "src": "modul", "id": "P11-009"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Penulisan kutipan dari sumber kedua yang benar adalah…", "opts": ["King (dalam Pratama, 2013: 29) mendefinisikan diskusi sebagai…", "King, Pratama (2013: 29) mendefinisikan diskusi sebagai…", "Pratama (King, 2013: 29) mendefinisikan diskusi sebagai…", "(King dan Pratama, 2013) mendefinisikan diskusi sebagai…"], "ans": 0, "why": "Sumber kedua: penulis asli (dalam penulis sumber yang dibaca, tahun: halaman).", "lvl": 1, "code": null, "src": "modul", "id": "P11-010"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Istilah untuk catatan kaki yang merujuk sumber sama tepat di atasnya adalah…", "opts": ["Ibid.", "op. cit.", "loc. cit.", "et al."], "ans": 0, "why": "Ibid. = sumber sama dengan tepat di atasnya; op. cit. = sumber sama tetapi sudah diselingi sumber lain.", "lvl": 1, "code": null, "src": "modul", "id": "P11-011"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Dalam footnote, nama penulis ditulis…", "opts": ["lengkap dan tidak dibalik", "dibalik (nama belakang dulu)", "hanya nama belakang", "hanya inisial"], "ans": 0, "why": "Footnote: nama lengkap tidak dibalik; daftar pustaka: nama dibalik.", "lvl": 1, "code": null, "src": "modul", "id": "P11-012"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Footnote yang merujuk sumber yang sama tetapi sudah diselingi sumber lain ditulis dengan…", "opts": ["op. cit.", "Ibid.", "sic!", "dkk."], "ans": 0, "why": "Op. cit. dipakai jika sumber sama tetapi melewati satu sumber lain.", "lvl": 2, "code": null, "src": "modul", "id": "P11-013"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Urutan unsur daftar pustaka menurut modul adalah…", "opts": ["nama, tahun, judul, kota terbit, penerbit", "judul, nama, tahun, penerbit, kota", "nama, judul, penerbit, kota, tahun", "tahun, nama, judul, penerbit, kota"], "ans": 0, "why": "Nama (dibalik). Tahun. Judul. Kota: Penerbit.", "lvl": 1, "code": null, "src": "modul", "id": "P11-014"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Nama penulis 'Syaiful Anwar, M.T.' dalam daftar pustaka ditulis…", "opts": ["Anwar, Syaiful.", "Syaiful Anwar, M.T.", "Anwar, Syaiful, M.T.", "S. Anwar."], "ans": 0, "why": "Nama dibalik dan gelar tidak dicantumkan.", "lvl": 1, "code": null, "src": "modul", "id": "P11-015"}, {"p": "P11", "tag": "pustaka", "type": "mcq", "q": "Alat manajer referensi yang disebut dalam materi adalah…", "opts": ["Mendeley, Zotero, EndNote", "Excel, Access, PowerPoint", "Canva, Figma, Photoshop", "Google Translate, Grammarly, KBBI"], "ans": 0, "why": "Kutipan bisa dibuat manual, otomatis lewat References di MS Word, atau dengan Mendeley/Zotero/EndNote.", "lvl": 1, "code": null, "src": "modul", "id": "P11-016"}, {"p": "P11", "tag": "kutipan", "type": "mcq", "q": "Penulisan kutipan tidak langsung yang paling efektif adalah…", "opts": ["Rahman (2022) menjelaskan bahwa literasi digital wajib dimiliki mahasiswa.", "Bahwa literasi digital wajib dimiliki mahasiswa menurut Rahman (2022).", "Menurut Rahman (2022) bahwa literasi digital wajib dimiliki mahasiswa.", "Menurut Rahman literasi digital wajib dimiliki mahasiswa (2022)."], "ans": 0, "why": "Nama (tahun) diikuti verba pelapor + bahwa. 'Menurut ... bahwa' adalah konjungsi ganda; tahun harus menempel pada nama.", "lvl": 2, "code": null, "src": "uts", "id": "P11-017"}], "cards": [{"id": "P01-C001", "p": "P01", "tag": "sejarah", "front": "Tonggak ejaan", "back": "Van Ophuijsen 1901 → Soewandi 1947 → EYD 1972 → EBI 2015 → EYD V 16 Agustus 2022"}, {"id": "P01-C002", "p": "P01", "tag": "kedudukan", "front": "Bahasa nasional vs negara", "back": "Nasional (Sumpah Pemuda): kebanggaan, identitas, pemersatu · Negara (UUD 1945 Psl 36): resmi kenegaraan, pendidikan, iptek"}, {"id": "P01-C003", "p": "P01", "tag": "sejarah", "front": "Tonggak bahasa Indonesia", "back": "1901 van Ophuijsen · 1908 Balai Pustaka · 1928 Sumpah Pemuda · 1933 Pujangga Baru · 1938 Kongres I Solo · 1945 UUD Pasal 36 · 1954 Kongres II Medan"}, {"id": "P01-C004", "p": "P01", "tag": "sejarah", "front": "Prasasti Melayu Kuno", "back": "Talang Tuo 684 M (Palembang) · Kota Kapur 686 M (Bangka) · Karang Berahi ±680 M (Jambi)"}, {"id": "P01-C005", "p": "P01", "tag": "kedudukan", "front": "Bahasa nasional vs bahasa negara", "back": "Nasional: Sumpah Pemuda 1928 → kebanggaan, identitas, pemersatu, penghubung antardaerah\nNegara: UUD 1945 Ps. 36 → resmi kenegaraan, pengantar pendidikan, perhubungan nasional, pengembangan iptek"}, {"id": "P01-C006", "p": "P01", "tag": "kedudukan", "front": "4 fungsi bahasa (Alwi dkk.)", "back": "pemersatu · pemberi kekhasan · pembawa kewibawaan · kerangka acuan"}, {"id": "P01-C007", "p": "P01", "tag": "ragam", "front": "Ragam menurut penutur", "back": "idiolek (perorangan) · dialek (wilayah) · kronolek (masa) · sosiolek (status sosial)"}, {"id": "P01-C008", "p": "P01", "tag": "ragam", "front": "Ragam menurut keformalan", "back": "beku → baku/resmi → usaha/konsultatif → santai/kasual → akrab/intim"}, {"id": "P01-C009", "p": "P01", "tag": "sejarah", "front": "Urutan ejaan", "back": "van Ophuijsen 1901 → Soewandi 1947 → (Melindo 1959 batal) → EYD 1972 → PUEBI 2015 → EYD V 2022"}, {"id": "P02-C001", "p": "P02", "tag": "kata", "front": "di- vs di", "back": "Awalan di- serangkai (ditulis) · kata depan di terpisah (di rumah, di atas)"}, {"id": "P02-C002", "p": "P02", "tag": "kata", "front": "Partikel pun", "back": "Dipisah: apa pun, siapa pun · Serangkai: walaupun, meskipun, adapun, kalaupun"}, {"id": "P02-C003", "p": "P02", "tag": "angka", "front": "Angka", "back": "Awal kalimat → huruf · Rp100.000,00 · abad ke-21 · 90-an"}, {"id": "P02-C004", "p": "P02", "tag": "tandabaca", "front": "Koma", "back": "Sebelum tetapi/melainkan/sedangkan · di antara rincian · setelah anak kalimat di depan induk"}, {"id": "P02-C005", "p": "P02", "tag": "kapital", "front": "Jabatan: kapital atau tidak?", "back": "Kapital jika diikuti nama orang/instansi/tempat: Bupati Magelang, Gubernur DIY\nKecil jika berdiri sendiri: dilantik menjadi bupati"}, {"id": "P02-C006", "p": "P02", "tag": "kapital", "front": "Geografi: kapital atau tidak?", "back": "Gunung Merapi, Danau Toba (diikuti nama diri)\nmendaki gunung (tanpa nama)\npisang ambon (nama jenis)\nbatik Pekalongan (khas budaya)"}, {"id": "P02-C007", "p": "P02", "tag": "kapital", "front": "Judul buku/karangan", "back": "Semua kata kapital, kecuali kata tugas di tengah: di, ke, dari, dan, yang, untuk, sebagai, dengan, terhadap, pada"}, {"id": "P02-C008", "p": "P02", "tag": "tandabaca", "front": "Koma & anak kalimat", "back": "Anak kalimat DI DEPAN → pakai koma (Jika hujan, saya...)\nAnak kalimat DI BELAKANG → tanpa koma (Saya ... jika hujan)\nTidak ada koma sebelum 'bahwa'"}, {"id": "P02-C009", "p": "P02", "tag": "tandabaca", "front": "Tanda hubung", "back": "anak-anak · se-Indonesia · ke-2 · 90-an · ber-KTP · di-smash"}, {"id": "P02-C010", "p": "P02", "tag": "tandabaca", "front": "Titik koma (;)", "back": "klausa setara tanpa kata hubung · perincian yang sudah berkoma · antar-sumber kutipan"}, {"id": "P02-C011", "p": "P02", "tag": "angka", "front": "dr. vs Dr. vs PT", "back": "dr. = dokter · Dr. = doktor · PT = perseroan terbatas (tanpa titik) · Rp, km tanpa titik"}, {"id": "P02-C012", "p": "P02", "tag": "angka", "front": "Angka atau huruf?", "back": "1–2 kata → huruf (tiga kali) · perincian berurutan → angka · ukuran & uang → angka (Rp50.000,00) · awal kalimat → jangan angka"}, {"id": "P04-C001", "p": "P04", "tag": "imbuhan", "front": "Peluluhan KPTS", "back": "k-p-t-s luluh dengan me-/pe- (menulis, memukul, menyapu) kecuali gugus konsonan (memproduksi)"}, {"id": "P04-C002", "p": "P04", "tag": "serapan", "front": "Kata baku", "back": "kreativitas · teknologi · modern · miliar · kuitansi · analisis · praktik · sistem"}, {"id": "P04-C003", "p": "P04", "tag": "diksi", "front": "Denotasi vs konotasi", "back": "Denotasi: makna sebenarnya · Konotasi: makna dengan nilai rasa"}, {"id": "P04-C004", "p": "P04", "tag": "serapan", "front": "4 cara menyerap kata asing", "back": "adopsi (supermarket) · adaptasi (pluralisasi) · penerjemahan (uji coba) · kreasi (suku cadang)"}, {"id": "P04-C005", "p": "P04", "tag": "imbuhan", "front": "Peluluhan K-T-S-P", "back": "meN-/peN- + K,T,S,P → luluh: mengonsumsi, menelaah, menyurvei, memelihara\nGugus konsonan → tidak luluh: mengkritik, mentransfer, memprotes"}, {"id": "P04-C006", "p": "P04", "tag": "imbuhan", "front": "Imbuhan yang ditulis serangkai", "back": "asing: multi, anti, semi, non, pra, infra, ultra, ekstra, intra\ndaerah: tuna, nara, pasca, swa, panca, dasa, maha, antar"}, {"id": "P04-C007", "p": "P04", "tag": "serapan", "front": "Kata baku sering keliru (1)", "back": "analisis · apotek · atlet · izin · jadwal · kualitas · kuitansi · miliar · nasihat · objek"}, {"id": "P04-C008", "p": "P04", "tag": "serapan", "front": "Kata baku sering keliru (2)", "back": "praktik · risiko · sistem · teknik · teoretis · mengubah · silakan · telantar · imbau · kreativitas"}, {"id": "P05-C001", "p": "P05", "tag": "ciri", "front": "7 ciri kalimat efektif", "back": "Kesepadanan · kecermatan · kehematan · kelogisan · kepaduan · keparalelan · ketegasan"}, {"id": "P05-C002", "p": "P05", "tag": "hemat", "front": "Pleonasme umum", "back": "adalah merupakan · naik ke atas · para … -… · agar supaya · sangat … sekali · demi untuk"}, {"id": "P05-C003", "p": "P05", "tag": "hemat", "front": "Preposisi di awal kalimat", "back": "Dalam/Di/Bagi/Kepada + subjek → subjek hilang\n'Dalam rapat itu membahas' ✗ → 'Rapat itu membahas' ✓"}, {"id": "P05-C004", "p": "P05", "tag": "hemat", "front": "Pemborosan yang sering muncul", "back": "adalah merupakan · agar supaya · sangat…sekali · sejak dari · para siswa-siswa · saling…satu sama lain · naik ke atas"}, {"id": "P05-C005", "p": "P05", "tag": "ciri", "front": "Pasangan konjungsi", "back": "baik…maupun · tidak hanya…tetapi juga · bukan…melainkan · tidak…tetapi · meskipun… (tanpa tetapi/namun)"}, {"id": "P06-C001", "p": "P06", "tag": "fungsi", "front": "Objek vs pelengkap", "back": "Objek bisa jadi subjek kalimat pasif · pelengkap tidak"}, {"id": "P06-C002", "p": "P06", "tag": "majemuk", "front": "Majemuk setara vs bertingkat", "back": "Setara: dan, atau, tetapi · Bertingkat: karena, ketika, jika, agar"}, {"id": "P07-C001", "p": "P07", "tag": "syarat", "front": "Syarat paragraf", "back": "Kepaduan · kesatuan · kelengkapan"}, {"id": "P07-C002", "p": "P07", "tag": "letak", "front": "Letak kalimat utama", "back": "Deduktif (awal) · induktif (akhir) · campuran (awal & akhir)"}, {"id": "P07-C003", "p": "P07", "tag": "kembang", "front": "Teknik pengembangan paragraf", "back": "umum-khusus · khusus-umum · generalisasi · definisi · sebab-akibat · akibat-sebab · analogi · kronologi · perbandingan · contoh · klasifikasi"}, {"id": "P10-C001", "p": "P10", "tag": "sistematika", "front": "Sistematika makalah", "back": "Pendahuluan (latar belakang, rumusan masalah, tujuan, manfaat) → Pembahasan → Penutup (simpulan, saran) → Daftar pustaka"}, {"id": "P10-C002", "p": "P10", "tag": "sistematika", "front": "Sistematika skripsi", "back": "BAB I Pendahuluan · BAB II Tinjauan Pustaka · BAB III Metode · BAB IV Hasil & Pembahasan · BAB V Penutup"}, {"id": "P11-C001", "p": "P11", "tag": "kutipan", "front": "Bodynote", "back": "Menurut Ahmad (2015), … · Ahmad (2015) menjelaskan … · … (Ahmad, 2015)"}, {"id": "P11-C002", "p": "P11", "tag": "kutipan", "front": "Format bodynote", "back": "Malik (2007: 202) menyatakan …\n… (Malik, 2007: 202).\nSumber kedua: King (dalam Pratama, 2013: 29)"}, {"id": "P11-C003", "p": "P11", "tag": "kutipan", "front": "Kutipan langsung pendek vs panjang", "back": "Pendek: < 4 baris, menyatu, pakai \"…\"\nPanjang: ≥ 4 baris, terpisah, menjorok 5-7 ketukan"}, {"id": "P11-C004", "p": "P11", "tag": "kutipan", "front": "Ibid. vs op. cit.", "back": "Ibid. = sumber sama, tepat di atasnya\nop. cit. = sumber sama, sudah diselingi sumber lain"}, {"id": "P11-C005", "p": "P11", "tag": "pustaka", "front": "Format daftar pustaka", "back": "Anwar, Syaiful. 2015. Judul Buku. Yogyakarta: Media Pustaka.\n(nama dibalik, tanpa gelar, Kota: Penerbit)"}]});
